INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C1','math',3,2,'u3',2,'원 알아보기 — 꼭짓점 없이 어느 쪽으로 보아도 똑같이 둥근 굽은 선을 원이라 하고, 길쭉한 모양·꼭짓점 있는 모양과 가려내며, 원은 선이라 선 위의 점만 원 위의 점임을 알기',ARRAY['4수03-06']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C2','math',3,2,'u3',2,'원의 중심과 반지름 — 한 점에서 같은 길이만큼 떨어진 점들이 원을 이루고, 그 한 점이 원의 중심(한 원에 하나), 중심과 원 위의 한 점을 이은 선분이 반지름(모두 같고 무수히 많음)임을 알기',ARRAY['4수03-06']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C3','math',3,2,'u3',3,'지름 — 원 위의 두 점을 이은 선분이 원의 중심을 지날 때 지름이라 하고, 한 원에서 지름은 모두 같고 무수히 많으며, 중심에 자를 먼저 대어 긋기',ARRAY['4수03-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C4','math',3,2,'u3',4,'지름과 반지름의 관계 — 한 원에서 지름은 반지름의 2배, 반지름은 지름의 반임을 알고 서로 구하기',ARRAY['4수03-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C5','math',3,2,'u3',4,'지름의 성질과 원의 크기 견주기 — 지름은 원을 똑같이 둘로 나누고 원 안에 그을 수 있는 가장 긴 선분임을 알며, 반지름과 지름이 섞이면 한 가지로 바꾸어 원의 크기를 견주기',ARRAY['4수03-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C6','math',3,2,'u3',5,'컴퍼스로 원 그리기 — 원의 중심을 정하고, 침과 연필 끝을 반지름만큼 벌려, 침을 중심에 꽂고 돌려 그리며, 지름이 주어지면 그 반만큼 벌리기',ARRAY['4수03-07']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C7','math',3,2,'u3',6,'원으로 무늬 만들기 — 모눈 위 원 무늬에서 원의 중심을 옮기는 규칙과 반지름이 바뀌는 규칙을 찾아 다음 원을 알아내고, 규칙을 정해 무늬를 그리기',ARRAY['4수03-06·4수03-07']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u3-C8','math',3,2,'u3',4,'여러 원으로 길이 구하기 — 맞닿은 원·상자 속 원·원 안의 원 그림에서 반지름과 지름이 몇 번 들어 있는지 찾아 선분의 길이를 구하기',ARRAY['4수03-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X01','math',3,'u3',ARRAY['M3-2-u3-C1']::text[],'원의 모양을 가려내지 못한다 — 굽은 선으로 둘러싸이거나 둥글어 보이면 길쭉한 모양·꼭짓점 있는 모양도 원이라고 한다','어느 쪽으로 보아도 똑같이 둥근지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X02','math',3,'u3',ARRAY['M3-2-u3-C1','M3-2-u3-C2','M3-2-u3-C6']::text[],'원 안이나 밖의 점도 원 위의 점이라고 한다 — 원은 굽은 선(테두리)이라는 것을 놓친다','선 위에 있는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X03','math',3,'u3',ARRAY['M3-2-u3-C2','M3-2-u3-C6']::text[],'원의 중심이 여러 개 있거나 원 위에 있다고 생각한다 — 중심은 원의 가장 안쪽 한 점이라는 것을 놓친다','중심은 한 원에 하나, 가장 안쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X04','math',3,'u3',ARRAY['M3-2-u3-C2','M3-2-u3-C3']::text[],'한 원에 반지름·지름이 1개나 몇 개뿐이라고 생각한다','원 위의 점마다 그을 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X05','math',3,'u3',ARRAY['M3-2-u3-C2','M3-2-u3-C3']::text[],'한 원에서 반지름(지름)은 그은 자리에 따라 길이가 다르다고 생각한다','한 원에서 반지름은 모두 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X06','math',3,'u3',ARRAY['M3-2-u3-C3','M3-2-u3-C5']::text[],'원 위의 두 점을 이은 선분이면 모두 지름이라고 한다 — 원의 중심을 지나는지 확인하지 않는다','중심을 지나는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X07','math',3,'u3',ARRAY['M3-2-u3-C2','M3-2-u3-C3','M3-2-u3-C5']::text[],'반지름과 지름의 이름(뜻)을 바꾸어 안다','반지름은 중심에서 원까지, 지름은 중심을 지나 원에서 원까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X08','math',3,'u3',ARRAY['M3-2-u3-C4','M3-2-u3-C6','M3-2-u3-C7','M3-2-u3-C8']::text[],'2배와 반을 거꾸로 한다 — 반지름으로 지름을 구할 때 반으로, 지름으로 반지름을 구할 때 2배로 한다','지름이 반지름보다 길어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X09','math',3,'u3',ARRAY['M3-2-u3-C4','M3-2-u3-C7']::text[],'지름과 반지름의 길이가 같다고 보아 2배나 반을 하지 않고 그대로 쓴다','지름 = 반지름 × 2') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X10','math',3,'u3',ARRAY['M3-2-u3-C5']::text[],'반지름과 지름이 섞인 원의 크기를 수만 보고 견준다','한 가지로 바꾸어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X11','math',3,'u3',ARRAY['M3-2-u3-C6']::text[],'컴퍼스를 지름만큼 벌린다 — 벌린 길이가 반지름이라는 것을 놓친다','벌리는 길이 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X12','math',3,'u3',ARRAY['M3-2-u3-C6','M3-2-u3-C7']::text[],'컴퍼스로 원을 그리는 차례·침을 꽂는 곳을 모른다 — 중심과 반지름을 먼저 정하지 않는다','중심 정하기 → 벌리기 → 돌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X13','math',3,'u3',ARRAY['M3-2-u3-C7']::text[],'무늬에서 원의 중심이 옮겨 가는 방향이나 칸 수를 잘못 읽는다','중심을 점으로 찍어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X14','math',3,'u3',ARRAY['M3-2-u3-C7']::text[],'무늬에서 반지름의 규칙(되풀이·늘어남)을 놓치고 바로 앞 원만 보고 정한다','처음부터 반지름을 차례로 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X15','math',3,'u3',ARRAY['M3-2-u3-C8','M3-2-u3-C6','M3-2-u3-C7']::text[],'여러 원으로 된 그림에서 반지름·지름이 몇 번 들어 있는지 잘못 센다','선분 위에 반지름을 하나씩 표시하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X16','math',3,'u3',ARRAY['M3-2-u3-C1','M3-2-u3-C2','M3-2-u3-C3','M3-2-u3-C4','M3-2-u3-C5','M3-2-u3-C6','M3-2-u3-C7','M3-2-u3-C8']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못 말한↔바르게 말한','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X17','math',3,'u3',ARRAY['M3-2-u3-C5']::text[],'지름이 원 안의 가장 긴 선분이고 원을 똑같이 둘로 나눈다는 것을 모른다','중심을 지나는 선분이 가장 길어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X18','math',3,'u3',ARRAY['M3-2-u3-C3']::text[],'반지름 두 개를 원의 중심에서 꺾어 이은 선도 지름이라고 한다 — 지름은 원의 중심을 지나는 곧은 선분 하나라는 것을 놓친다(지도서 285 「반지름 2개를 그어 지름을 표시」)','지름은 꺾이지 않은 선분 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X19','math',3,'u3',ARRAY['M3-2-u3-C3']::text[],'원의 중심을 지나기만 하면 원 밖까지 뻗은 선도 지름이라고 한다 — 지름의 두 끝이 원 위의 점이라는 것을 놓친다(익힘 41 3번)','지름의 두 끝은 원 위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X20','math',3,'u3',ARRAY['M3-2-u3-C2','M3-2-u3-C3','M3-2-u3-C4']::text[],'원의 중심에서 시작하는지·중심을 지나는지 보지 않고 그림에 적힌 아무 선분의 길이를 반지름(지름)으로 쓴다(익힘 41 6번·교과서 75 3번의 함정 선분)','선분이 원의 중심과 이어져 있는지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X21','math',3,'u3',ARRAY['M3-2-u3-C5']::text[],'원의 중심(점)이 원을 똑같이 둘로 나눈다고 말한다 — 원을 둘로 나누는 것은 지름(선분)이다(교과서 75 4번)','점은 나누지 못해요 — 지름이 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X22','math',3,'u3',ARRAY['M3-2-u3-C5']::text[],'둘레에 놓인 그림에 끌려 원의 크기를 눈대중으로 판단한다 — 지름을 재어 견주지 않는다(익힘 43 착시)','눈으로 보지 말고 지름을 재어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X23','math',3,'u3',ARRAY['M3-2-u3-C1','M3-2-u3-C2']::text[],'원을 만들 때 중심을 움직이거나 중심과의 거리를 일정하게 유지하지 않아도 원이 된다고 여긴다(지도서 269·284 평가 1)','중심은 고정, 거리는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u3-X24','math',3,'u3',ARRAY['M3-2-u3-C2','M3-2-u3-C6']::text[],'줄이나 띠종이 구멍까지의 길이(반지름)가 길수록 원이 커진다는 것을 모른다(교과서 64·익힘 42 8번)','반지름이 길면 원이 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#1','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C1',1,'mc','auto','「준비하기」 — 원은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":1,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"「준비하기」 — 원은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"},{"t":"㉱","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉮만 그래요 — 나머지는 꼭짓점이 있거나 한쪽으로 길쭉(찌그러진 모양)해요.","굽은 선으로 둘러싸여도 찌그러져 있으면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"circle":[[[45,45],34.5]]},{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,63.0],[76.2,63.0]]]},{"w":90,"h":90,"oval":[[45,45,39.0,24.0]]},{"w":90,"h":90,"poly":[[[20.6,20.6],[20.6,69.4],[69.4,69.4],[69.4,20.6]]]}]},"variant_rule":{"alt":[{"stem":"조금 찌그러진 모양도 섞여 있어요. 원은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"},{"t":"㉱","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉯만 그래요 — 나머지는 꼭짓점이 있거나 한쪽으로 길쭉(찌그러진 모양)해요.","굽은 선으로 둘러싸여도 찌그러져 있으면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"oval":[[45,45,40.5,19.5]]},{"w":90,"h":90,"circle":[[[45,45],33.0]]},{"w":90,"h":90,"oval":[[45,45,36.0,30.7]]},{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#2','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C1',1,'ox','auto','「준비하기」 — 원에는 꼭짓점이 있어요.',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":2,"concept":"M3-2-u3-C1","difficulty":1,"kind":"ox","stem":"「준비하기」 — 원에는 꼭짓점이 있어요.","answer":"X","reason_options":[{"t":"원은 굽은 선으로만 되어 있어 꼭짓점이 없어서","correct":true},{"t":"둥근 모양에도 뾰족한 곳이 있어서","mis":"M3-2-u3-X01"}],"mis":"M3-2-u3-X01","explanation":["원은 굽은 선으로만 되어 있어요.","꼭짓점도, 곧은 선도 없어요.","그래서 이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"「준비하기」 — 원에는 곧은 선이 있어요.","answer":"X","reason_options":[{"t":"원은 굽은 선으로만 되어 있어서","correct":true},{"t":"원 안에 반지름이 그어져 있으면 원에도 곧은 선이 있어서","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로만 되어 있어요.","원 안에 그은 반지름·지름은 원이 아니라 원 안의 선분이에요.","그래서 이 말은 틀렸어요(X)."]},{"stem":"「준비하기」 — 동전을 본떠 그리면 원을 그릴 수 있어요.","answer":"O","reason_options":[{"t":"동전의 둘레는 어느 쪽으로 보아도 똑같이 둥글어서","correct":true},{"t":"동전에는 꼭짓점이 있어서","mis":"M3-2-u3-X01"}],"explanation":["동전의 둘레는 꼭짓점이 없어요.","어느 쪽으로 보아도 똑같이 둥글어요.","본떠 그리면 원이 돼요(O)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#3','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C1',1,'mc','auto','원을 본떠 그릴 수 있는 물건은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":3,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"원을 본떠 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"연필꽂이의 바닥","correct":true},{"t":"네모난 상자","mis":"M3-2-u3-X01"},{"t":"케이크 조각","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 어느 쪽으로 보아도 똑같이 둥근 물건을 골라요.","연필꽂이의 바닥은 원 모양이에요.","상자·케이크 조각은 꼭짓점이 있어서 본뜨면 원이 되지 않아요."],"variant_rule":{"alt":[{"stem":"원을 본떠 그릴 수 있는 물건은 어느 것인가요? (컵, 상자, 케이크 조각)","options":[{"t":"컵의 바닥","correct":true},{"t":"상자의 옆면","mis":"M3-2-u3-X01"},{"t":"케이크 조각의 옆면","mis":"M3-2-u3-X01"}],"explanation":["컵의 바닥은 똑같이 둥근 모양이에요.","컵 바닥을 대고 따라 그리면 원이 돼요.","상자·케이크 조각의 옆면은 꼭짓점이 있어 원이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#4','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',1,'mc','auto','뉴질랜드 원주민은 포이를 돌려 원을 만들며 춤을 춰요. 포이는 어느 곳을 중심으로 돌아가나요?',ARRAY['M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":4,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"뉴질랜드 원주민은 포이를 돌려 원을 만들며 춤을 춰요. 포이는 어느 곳을 중심으로 돌아가나요?","options":[{"t":"줄을 잡은 손","correct":true},{"t":"줄 끝에 매단 솜 공","mis":"M3-2-u3-X03"},{"t":"줄의 한가운데","mis":"M3-2-u3-X03"},{"t":"포이가 지나간 둥근 자리","mis":"M3-2-u3-X02"}],"explanation":["포이는 솜으로 만든 공을 줄에 매단 것이에요.","줄을 잡은 손은 움직이지 않고, 공이 손 둘레를 돌아요.","그래서 줄을 잡은 손이 원의 중심이에요."],"variant_rule":{"alt":[{"stem":"포이를 돌릴 때 줄의 길이를 짧게 하면 만들어지는 원의 크기는 어떻게 되나요?","options":[{"t":"작아져요","correct":true},{"t":"커져요","mis":"M3-2-u3-X24"},{"t":"그대로예요","mis":"M3-2-u3-X24"},{"t":"원이 생기지 않아요","mis":"M3-2-u3-X23"}],"explanation":["줄을 잡은 손이 원의 중심이고, 줄의 길이가 반지름처럼 돼요.","줄이 짧으면 공이 손 가까이에서 돌아요.","그래서 원의 크기가 작아져요."]},{"stem":"포이를 돌릴 때 줄의 길이를 길게 하면 만들어지는 원의 크기는 어떻게 되나요?","options":[{"t":"커져요","correct":true},{"t":"작아져요","mis":"M3-2-u3-X24"},{"t":"그대로예요","mis":"M3-2-u3-X24"},{"t":"원이 생기지 않아요","mis":"M3-2-u3-X23"}],"explanation":["줄을 잡은 손이 원의 중심이에요.","줄이 길면 공이 손에서 더 멀리 떨어져 돌아요.","그래서 원의 크기가 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#5','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'mc','auto','자를 사용하여 주어진 한 점에서 같은 길이만큼 떨어진 곳에 점을 여러 개 찍고, 찍은 점을 이어 원을 그렸어요. 원을 더 정확하게 그리려면 어떻게 해야 하나요?',ARRAY['M3-2-u3-X04','M3-2-u3-X05','M3-2-u3-X01']::text[],true,'{"seq":5,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"자를 사용하여 주어진 한 점에서 같은 길이만큼 떨어진 곳에 점을 여러 개 찍고, 찍은 점을 이어 원을 그렸어요. 원을 더 정확하게 그리려면 어떻게 해야 하나요?","options":[{"t":"점을 빈틈없이 많이 찍어요","correct":true},{"t":"점을 몇 개만 찍어요","mis":"M3-2-u3-X04"},{"t":"점마다 떨어진 길이를 다르게 해요","mis":"M3-2-u3-X05"},{"t":"찍은 점을 곧은 선으로 이어요","mis":"M3-2-u3-X01"}],"explanation":["원은 한 점에서 같은 길이만큼 떨어진 점들로 이루어져요.","그런 점을 빈틈없이 많이 찍을수록 원에 가까워져요.","점을 이을 때도 곧은 선이 아니라 굽은 선으로 이어요."],"variant_rule":{"alt":[{"stem":"자로 점을 찍어 원을 그릴 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"주어진 한 점에서 모두 같은 길이만큼 떨어진 곳에 찍어요","correct":true},{"t":"점마다 떨어진 길이를 다르게 해요","mis":"M3-2-u3-X05"},{"t":"주어진 점을 옮겨 가며 찍어요","mis":"M3-2-u3-X23"},{"t":"점을 한 줄로 나란히 찍어요","mis":"M3-2-u3-X01"}],"explanation":["주어진 한 점이 원의 중심이 돼요.","그 점에서 같은 길이만큼 떨어진 곳에 점을 찍어요.","중심을 옮기거나 길이를 바꾸면 원이 되지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#6','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'mc','auto','누름 못과 띠종이를 사용하여 원을 그렸어요. 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03']::text[],true,'{"seq":6,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"누름 못과 띠종이를 사용하여 원을 그렸어요. 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["누름 못으로 띠종이와 종이를 고정하고, 연필을 구멍에 꽂아 한 바퀴 돌려요.","누름 못이 꽂힌 점은 움직이지 않는 가운데 점이에요.","이 점을 원의 중심이라고 해요."],"variant_rule":{"alt":[{"stem":"점 ㅇ은 누름 못이 꽂힌 점이에요. 원의 중심 ㅇ과 원 위의 한 점 ㄱ을 이은 선분 ㅇㄱ을 원의 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["누름 못이 꽂힌 점 ㅇ이 원의 중심이에요.","원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","선분 ㅇㄱ은 반지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[102.6,35.4,"ne"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#7','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'sa','auto','원에 반지름을 여러 개 긋고 재었더니 선분 ㅇㄱ은 2 cm였어요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u3-C2","difficulty":2,"kind":"sa","stem":"원에 반지름을 여러 개 긋고 재었더니 선분 ㅇㄱ은 2 cm였어요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ·ㄴ·ㄷ은 원 위의 점이에요.","선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 2 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[37.0,54.2,"w"],"ㄷ":[86.4,100.3,"s"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[91.3,42.9],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「안에 알맞은 수」 — 원의 중심 ㅇ에서 그은 선분 ㅇㄱ은 5 cm였어요. 선분 ㅇㄴ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ·ㄴ·ㄷ은 원 위의 점이에요.","선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 5 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[55.5,29.2,"nw"],"ㄴ":[66.2,101.0,"s"],"ㄷ":[112.3,51.6,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[54.9,46.7],"5 cm"]]}],"tag":false}},{"stem":"원에 반지름 3개를 그었어요. 선분 ㅇㄱ은 4 cm였어요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ·ㄴ·ㄷ은 원 위의 점이에요.","선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[41.2,82.5,"sw"],"ㄴ":[113.0,71.8,"e"],"ㄷ":[63.6,25.7,"n"],"ㅇ":[75,63.0,"ne"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[58.7,83.1],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#8','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'mc','auto','엄지손가락을 중심으로 집게손가락을 한 바퀴 돌려 원을 만들어요. 원을 정확하게 만들려면 어떻게 해야 하나요?',ARRAY['M3-2-u3-X23']::text[],true,'{"seq":8,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"엄지손가락을 중심으로 집게손가락을 한 바퀴 돌려 원을 만들어요. 원을 정확하게 만들려면 어떻게 해야 하나요?","options":[{"t":"엄지손가락은 움직이지 않고, 두 손가락 사이를 똑같이 벌린 채 돌려요","correct":true},{"t":"엄지손가락도 함께 움직이며 돌려요","mis":"M3-2-u3-X23"},{"t":"돌리면서 두 손가락 사이를 넓혔다 좁혔다 해요","mis":"M3-2-u3-X23"},{"t":"집게손가락을 반 바퀴만 돌려요","mis":"M3-2-u3-X23"}],"explanation":["방법은 달라도 한 곳을 중심으로 일정한 길이만큼 벌리고 한 바퀴를 돌려요.","엄지손가락(중심)이 움직이면 원이 아닌 모양이 돼요.","중심은 고정하고, 중심과의 거리는 그대로 유지해야 원이 돼요."],"variant_rule":{"alt":[{"stem":"한 발을 중심으로 다른 발을 한 바퀴 돌려 원을 만들어요. 원을 정확하게 만들려면 어떻게 해야 하나요?","options":[{"t":"중심이 되는 발은 제자리에 두고, 두 발 사이를 똑같이 유지하며 돌려요","correct":true},{"t":"중심이 되는 발도 따라 움직여요","mis":"M3-2-u3-X23"},{"t":"돌면서 두 발 사이를 점점 넓혀요","mis":"M3-2-u3-X23"},{"t":"다른 발을 반 바퀴만 돌려요","mis":"M3-2-u3-X23"}],"explanation":["방법은 달라도 한 곳을 중심으로 일정한 길이만큼 벌리고 한 바퀴를 돌려요.","중심이 되는 발(중심)이 움직이면 원이 아닌 모양이 돼요.","중심은 고정하고, 중심과의 거리는 그대로 유지해야 원이 돼요."]},{"stem":"두 사람이 손을 잡고 한 사람은 제자리에서, 다른 사람은 그 주변을 한 바퀴 돌아 원을 만들어요. 원을 정확하게 만들려면 어떻게 해야 하나요?","options":[{"t":"제자리에 선 사람은 움직이지 않고, 두 사람 사이의 거리를 똑같이 유지해요","correct":true},{"t":"제자리에 선 사람도 함께 걸어요","mis":"M3-2-u3-X23"},{"t":"도는 사람이 가까이 왔다 멀어졌다 해요","mis":"M3-2-u3-X23"},{"t":"도는 사람이 반 바퀴만 돌아요","mis":"M3-2-u3-X23"}],"explanation":["방법은 달라도 한 곳을 중심으로 일정한 길이만큼 벌리고 한 바퀴를 돌려요.","제자리에 선 사람(중심)이 움직이면 원이 아닌 모양이 돼요.","중심은 고정하고, 중심과의 거리는 그대로 유지해야 원이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#9','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C1',2,'mc','auto','원 위의 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],true,'{"seq":9,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄴ만 선 위에 있어요. 점 ㄱ은 원 안, 점 ㄷ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄴ":[93.8,30.5,"ne"],"ㄱ":[59.1,68.8,"nw"],"ㄷ":[120.5,89.2,"se"]},"circle":[[[75,63.0],37.5]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄱ만 선 위에 있어요. 점 ㄷ은 원 안, 점 ㄴ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[39.8,50.2,"w"],"ㄷ":[83.4,77.6,"se"],"ㄴ":[93.0,13.7,"n"]},"circle":[[[75,63.0],37.5]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄷ만 선 위에 있어요. 점 ㄴ은 원 안, 점 ㄱ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[68.5,99.9,"s"],"ㄴ":[87.9,52.2,"ne"],"ㄱ":[23.3,53.9,"w"]},"circle":[[[75,63.0],37.5]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_basic#10','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',3,'ox','auto','지아는 「한 원에 반지름은 1개입니다.」라고 말했어요. 지아의 말이 맞나요?',ARRAY['M3-2-u3-X04']::text[],true,'{"seq":10,"concept":"M3-2-u3-C2","difficulty":3,"kind":"ox","stem":"지아는 「한 원에 반지름은 1개입니다.」라고 말했어요. 지아의 말이 맞나요?","answer":"X","reason_options":[{"t":"원 위의 점마다 반지름을 그을 수 있어 무수히 많아서","correct":true},{"t":"원의 중심이 하나라서 반지름도 하나뿐이라서","mis":"M3-2-u3-X04"}],"mis":"M3-2-u3-X04","explanation":["반지름은 원의 중심과 원 위의 한 점을 이은 선분이에요.","원 위의 점은 무수히 많으니 반지름도 무수히 많이 그을 수 있어요.","지아의 말은 틀렸어요(X) — 한 원에 원의 중심이 1개예요."],"variant_rule":{"alt":[{"stem":"원에 반지름을 여러 개 긋고 재어 보니 모두 2 cm였어요. 「한 원에서 반지름은 모두 같습니다.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"원의 중심에서 원 위의 어느 점까지나 길이가 같아서","correct":true},{"t":"그은 방향마다 길이가 달라서","mis":"M3-2-u3-X05"}],"explanation":["원은 원의 중심에서 같은 길이만큼 떨어진 점들로 이루어져요.","그래서 어느 쪽으로 그어도 반지름의 길이는 같아요.","맞는 말이에요(O)."]},{"stem":"점 ㄱ은 원의 안쪽에 있어요. 「원의 안쪽에 있는 점 ㄱ도 원 위의 점이에요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"원은 굽은 선이라 선 위에 있는 점만 원 위의 점이라서","correct":true},{"t":"원의 안쪽도 모두 원이라서","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 선으로 이루어진 도형이에요.","원의 안쪽 부분은 원이 아니에요.","점 ㄱ은 원 위의 점이 아니에요(X)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#1','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C1',2,'mc','auto','원이 아닌 것은 어느 것인가요?',ARRAY['M3-2-u3-X16']::text[],true,'{"seq":1,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원이 아닌 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M3-2-u3-X16"},{"t":"㉯","mis":"M3-2-u3-X16"},{"t":"㉱","mis":"M3-2-u3-X16"}],"explanation":["크기는 달라도 어느 쪽으로 보아도 똑같이 둥글면 모두 원이에요.","㉰는 한쪽으로 조금 길쭉해요 — 중심에서 테두리까지의 길이가 모두 같지 않아요.","「원이 아닌 것」을 묻는 문제예요 — 찌그러진 모양(타원)은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"circle":[[[45,45],34.5]]},{"w":90,"h":90,"circle":[[[45,45],24.0]]},{"w":90,"h":90,"oval":[[45,45,37.5,30.0]]},{"w":90,"h":90,"circle":[[[45,45],30.0]]}]},"variant_rule":{"alt":[{"stem":"「타원도 원일까?」 — 원이 아닌 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u3-X16"},{"t":"㉰","mis":"M3-2-u3-X16"},{"t":"㉱","mis":"M3-2-u3-X16"}],"explanation":["크기는 달라도 어느 쪽으로 보아도 똑같이 둥글면 모두 원이에요.","㉯는 한쪽으로 조금 길쭉해요 — 중심에서 테두리까지의 길이가 모두 같지 않아요.","「원이 아닌 것」을 묻는 문제예요 — 찌그러진 모양(타원)은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"circle":[[[45,45],27.0]]},{"w":90,"h":90,"oval":[[45,45,36.0,32.2]]},{"w":90,"h":90,"circle":[[[45,45],36.0]]},{"w":90,"h":90,"circle":[[[45,45],21.0]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#2','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',2,'mc','auto','누름 못과 띠종이로 원을 그렸어요. 띠종이의 구멍 ㄴ에 누름 못을 꽂고, 구멍 ㄷ에 연필을 꽂아 한 바퀴 돌렸어요. 원의 중심은 어느 것인가요?',ARRAY['M3-2-u3-X03']::text[],true,'{"seq":2,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"누름 못과 띠종이로 원을 그렸어요. 띠종이의 구멍 ㄴ에 누름 못을 꽂고, 구멍 ㄷ에 연필을 꽂아 한 바퀴 돌렸어요. 원의 중심은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X03"},{"t":"점 ㄷ","mis":"M3-2-u3-X03"},{"t":"점 ㄹ","mis":"M3-2-u3-X03"}],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","점 ㄷ·ㄹ은 원 위의 점, 점 ㄱ은 원 안의 점이에요.","원의 중심은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[107.6,47.8,"ne"],"ㅁ":[123.9,40.2,"ne"],"ㄱ":[55.9,57.9,"nw"],"ㄹ":[102.6,86.1,"se"],"ㄴ":[75,63.0,"sw"]},"circle":[[[75,63.0],36.0]],"seg":[["ㄴ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"누름 못은 구멍 ㄴ에, 연필은 구멍 ㄷ에 꽂아 원을 그렸어요. 원을 더 크게 그리려면 연필을 어디에 꽂아야 하나요?","options":[{"t":"구멍 ㅁ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X24"},{"t":"구멍 ㄴ","mis":"M3-2-u3-X12"},{"t":"구멍 ㄷ 그대로","mis":"M3-2-u3-X24"}],"explanation":["누름 못에서 연필까지가 반지름이에요.","누름 못에서 더 먼 구멍에 연필을 꽂으면 반지름이 길어져요.","그래서 구멍 ㅁ에 꽂으면 원이 더 커져요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[107.6,47.8,"ne"],"ㅁ":[123.9,40.2,"ne"],"ㄱ":[55.9,57.9,"nw"],"ㄹ":[102.6,86.1,"se"],"ㄴ":[75,63.0,"sw"]},"circle":[[[75,63.0],36.0]],"seg":[["ㄴ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#3','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'mc','auto','친구와 손을 잡고, 친구는 제자리에서 나는 그 주변을 한 바퀴 돌아 원을 만들었는데 원이 찌그러졌어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u3-X23']::text[],true,'{"seq":3,"concept":"M3-2-u3-C2","difficulty":3,"kind":"mc","stem":"친구와 손을 잡고, 친구는 제자리에서 나는 그 주변을 한 바퀴 돌아 원을 만들었는데 원이 찌그러졌어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 사람 사이의 거리가 일정하지 않았어요","correct":true},{"t":"제자리에 선 친구가 움직이지 않았어요","mis":"M3-2-u3-X23"},{"t":"한 바퀴를 다 돌았어요","mis":"M3-2-u3-X23"},{"t":"너무 천천히 돌았어요","mis":"M3-2-u3-X23"}],"explanation":["원을 만들려면 중심은 움직이지 않아야 해요.","그리고 중심과 도는 쪽 사이의 거리가 일정해야 해요.","거리가 달라지면 반지름이 일정하지 않아 원이 찌그러져요."],"variant_rule":{"alt":[{"stem":"엄지손가락을 중심으로 집게손가락을 한 바퀴 돌려 원을 만들었는데 원이 찌그러졌어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"엄지손가락과 집게손가락 사이의 거리가 일정하지 않았어요","correct":true},{"t":"엄지손가락이 움직이지 않았어요","mis":"M3-2-u3-X23"},{"t":"한 바퀴를 다 돌았어요","mis":"M3-2-u3-X23"},{"t":"너무 천천히 돌았어요","mis":"M3-2-u3-X23"}],"explanation":["원을 만들려면 중심은 움직이지 않아야 해요.","그리고 중심과 도는 쪽 사이의 거리가 일정해야 해요.","거리가 달라지면 반지름이 일정하지 않아 원이 찌그러져요."]},{"stem":"한 발을 중심으로 다른 발을 한 바퀴 돌려 원을 만들었는데 원이 찌그러졌어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"중심이 되는 발과 다른 발 사이의 거리가 일정하지 않았어요","correct":true},{"t":"중심이 되는 발이 움직이지 않았어요","mis":"M3-2-u3-X23"},{"t":"한 바퀴를 다 돌았어요","mis":"M3-2-u3-X23"},{"t":"너무 천천히 돌았어요","mis":"M3-2-u3-X23"}],"explanation":["원을 만들려면 중심은 움직이지 않아야 해요.","그리고 중심과 도는 쪽 사이의 거리가 일정해야 해요.","거리가 달라지면 반지름이 일정하지 않아 원이 찌그러져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#4','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'error','auto','원의 중심과 반지름에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X16']::text[],true,'{"seq":4,"concept":"M3-2-u3-C2","difficulty":3,"kind":"error","stem":"원의 중심과 반지름에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"지아 — 「한 원에 반지름은 1개입니다.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"}],"explanation":["한 원에 원의 중심은 1개예요.","반지름은 원 위의 점마다 그을 수 있어 무수히 많아요.","지아의 말이 잘못이에요."],"variant_rule":{"alt":[{"stem":"원에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"건우 — 「한 원에 반지름은 2개 그을 수 있어.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"}],"explanation":["반지름은 원의 중심과 원 위의 한 점을 이은 선분이에요.","원 위의 점은 무수히 많아서 반지름도 무수히 많아요.","건우의 말이 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#5','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'sa','auto','원의 중심 ㅇ에서 원 위의 세 점 ㄱ, ㄴ, ㄷ까지 반지름을 그었어요. 선분 ㅇㄱ이 2 cm일 때, 세 반지름의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C2","difficulty":3,"kind":"sa","stem":"원의 중심 ㅇ에서 원 위의 세 점 ㄱ, ㄴ, ㄷ까지 반지름을 그었어요. 선분 ㅇㄱ이 2 cm일 때, 세 반지름의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 2 cm예요.","2 + 2 + 2 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[104.9,37.9,"ne"],"ㄴ":[36.1,61.0,"w"],"ㄷ":[92.7,97.7,"se"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[87.5,40.3],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심 ㅇ에서 원 위의 세 점 ㄱ, ㄴ, ㄷ까지 반지름을 그었어요. 선분 ㅇㄱ이 5 cm일 때, 세 반지름의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 5 cm예요.","5 + 5 + 5 = 15(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[68.2,24.6,"n"],"ㄴ":[53.8,95.7,"sw"],"ㄷ":[113.9,65.0,"e"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[61.6,40.8],"5 cm"]]}],"tag":false}},{"stem":"원의 중심 ㅇ에서 원 위의 세 점 ㄱ, ㄴ, ㄷ까지 반지름을 그었어요. 선분 ㅇㄱ이 4 cm일 때, 세 반지름의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 4 cm예요.","4 + 4 + 4 = 12(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㄴ":[110.9,78.2,"se"],"ㄷ":[70.2,24.3,"n"],"ㅇ":[75,63.0,"ne"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[55.5,80.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#6','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C1',3,'sa','auto','원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C1","difficulty":3,"kind":"sa","stem":"원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["원은 굽은 선 — 선 위에 놓인 점만 원 위의 점이에요.","원 안의 점 2개, 원 밖의 점 1개는 세지 않아요.","원 위의 점은 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[110.2,50.2,"e"],"ㄴ":[62.2,27.8,"n"],"ㄷ":[62.2,98.2,"s"],"ㄹ":[84.4,79.2,"se"],"ㅁ":[62.7,58.5,"nw"],"ㅂ":[100.3,19.2,"ne"]},"circle":[[[75,63.0],37.5]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원은 굽은 선 — 선 위에 놓인 점만 원 위의 점이에요.","원 안의 점 1개, 원 밖의 점 2개는 세지 않아요.","원 위의 점은 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[87.8,27.8,"n"],"ㄴ":[39.8,75.8,"w"],"ㄷ":[92.9,73.3,"se"],"ㄹ":[42.5,24.2,"nw"],"ㅁ":[83.5,111.0,"s"]},"circle":[[[75,63.0],37.5]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["원은 굽은 선 — 선 위에 놓인 점만 원 위의 점이에요.","원 안의 점 1개, 원 밖의 점 1개는 세지 않아요.","원 위의 점은 4개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[112.5,63.0,"e"],"ㄴ":[75.0,25.5,"n"],"ㄷ":[37.5,63.0,"w"],"ㄹ":[75.0,100.5,"s"],"ㅁ":[88.3,49.7,"ne"],"ㅂ":[39.2,98.8,"sw"]},"circle":[[[75,63.0],37.5]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#7','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'ox','auto','선분 ㅇㄱ은 원의 중심 ㅇ과 원 위의 한 점 ㄱ을 이은 선분이고, 길이는 2 cm예요. 「원의 반지름은 선분 ㅇㄱ이에요. 그 길이를 말할 때 반지름이 2 cm라고도 해요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X07']::text[],true,'{"seq":7,"concept":"M3-2-u3-C2","difficulty":3,"kind":"ox","stem":"선분 ㅇㄱ은 원의 중심 ㅇ과 원 위의 한 점 ㄱ을 이은 선분이고, 길이는 2 cm예요. 「원의 반지름은 선분 ㅇㄱ이에요. 그 길이를 말할 때 반지름이 2 cm라고도 해요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름은 선분이고, 그 길이를 말할 때도 반지름이라고 하기 때문에","correct":true},{"t":"반지름은 길이일 뿐 선분이라고 할 수 없어서","mis":"M3-2-u3-X07"}],"mis":"M3-2-u3-X07","explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이은 선분 ㅇㄱ이에요.","길이를 잴 때는 「반지름은 2 cm」라고도 말해요.","두 말 모두 맞아요(O)."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[91.3,42.9],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선분 ㅇㄱ과 선분 ㅇㄴ은 원의 중심 ㅇ에서 원 위의 점까지 그은 선분이에요. 「두 선분의 길이는 같아요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"둘 다 한 원의 반지름이라서","correct":true},{"t":"그은 방향이 달라 길이도 달라서","mis":"M3-2-u3-X05"}],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요.","맞는 말이에요(O)."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[104.9,37.9,"ne"],"ㄴ":[36.6,69.8,"w"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#8','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',4,'sa','auto','원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형 ㅇㄱㄴ을 만들었어요. 이 원의 반지름이 5 cm일 때, 선분 ㅇㄱ과 선분 ㅇㄴ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C2","difficulty":4,"kind":"sa","stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형 ㅇㄱㄴ을 만들었어요. 이 원의 반지름이 5 cm일 때, 선분 ㅇㄱ과 선분 ㅇㄴ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","두 선분은 모두 5 cm예요(선분 ㄱㄴ은 반지름이 아니에요).","5 + 5 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[111.6,49.7,"e"],"ㄴ":[45.1,37.9,"nw"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형 ㅇㄱㄴ을 만들었어요. 이 원의 반지름이 2 cm일 때, 선분 ㅇㄱ과 선분 ㅇㄴ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","두 선분은 모두 2 cm예요(선분 ㄱㄴ은 반지름이 아니에요).","2 + 2 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㄴ":[104.9,88.1,"se"],"ㅇ":[75,63.0,"n"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형 ㅇㄱㄴ을 만들었어요. 이 원의 반지름이 4 cm일 때, 선분 ㅇㄱ과 선분 ㅇㄴ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","두 선분은 모두 4 cm예요(선분 ㄱㄴ은 반지름이 아니에요).","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[68.2,24.6,"n"],"ㄴ":[45.1,88.1,"sw"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#9','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',4,'mc','auto','반지름이 2 cm인 원이 있어요. 점 ㄱ은 원의 안쪽에, 점 ㄷ은 원의 바깥쪽에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u3-X02','M3-2-u3-X16']::text[],true,'{"seq":9,"concept":"M3-2-u3-C2","difficulty":4,"kind":"mc","stem":"반지름이 2 cm인 원이 있어요. 점 ㄱ은 원의 안쪽에, 점 ㄷ은 원의 바깥쪽에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"선분 ㅇㄱ은 2 cm보다 짧고, 선분 ㅇㄷ은 2 cm보다 길어요","correct":true},{"t":"선분 ㅇㄱ과 선분 ㅇㄷ은 모두 2 cm예요","mis":"M3-2-u3-X02"},{"t":"선분 ㅇㄱ은 2 cm보다 길고, 선분 ㅇㄷ은 2 cm보다 짧아요","mis":"M3-2-u3-X16"},{"t":"선분 ㅇㄷ이 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["원 위의 점까지는 꼭 반지름 2 cm예요.","원 안의 점은 그보다 가깝고, 원 밖의 점은 그보다 멀어요.","원 위에 있지 않은 점까지의 선분은 반지름이 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원이 있어요. 점 ㄱ은 원의 안쪽에, 점 ㄷ은 원의 바깥쪽에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"선분 ㅇㄱ은 5 cm보다 짧고, 선분 ㅇㄷ은 5 cm보다 길어요","correct":true},{"t":"선분 ㅇㄱ과 선분 ㅇㄷ은 모두 5 cm예요","mis":"M3-2-u3-X02"},{"t":"선분 ㅇㄱ은 5 cm보다 길고, 선분 ㅇㄷ은 5 cm보다 짧아요","mis":"M3-2-u3-X16"},{"t":"선분 ㅇㄷ이 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["원 위의 점까지는 꼭 반지름 5 cm예요.","원 안의 점은 그보다 가깝고, 원 밖의 점은 그보다 멀어요.","원 위에 있지 않은 점까지의 선분은 반지름이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L02_challenge#10','math',3,2,'u3','L02','tb_g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',4,'essay','teacher','운동장에서 짝과 함께 줄 하나로 큰 원을 만들려고 해요. 두 사람이 각각 어떻게 해야 하는지 쓰고, 그렇게 하면 원이 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C2","difficulty":4,"kind":"essay","stem":"운동장에서 짝과 함께 줄 하나로 큰 원을 만들려고 해요. 두 사람이 각각 어떻게 해야 하는지 쓰고, 그렇게 하면 원이 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 사람은 원의 중심이 되어 줄의 한쪽 끝을 잡고 제자리에 서 있는다. 다른 사람은 줄의 다른 끝을 잡고 줄이 팽팽하게 반지름이 되도록 당긴 채 한 바퀴 돈다. 중심에서 같은 길이만큼 떨어진 곳을 지나가므로 원이 된다.","scoring_points":["한 사람이 원의 중심이 되어 움직이지 않는다고 썼는가","줄을 팽팽하게(반지름이 되게) 당겨 한 바퀴 돈다고 썼는가","중심에서 같은 거리의 점들이라 원이 된다는 까닭을 썼는가"]},"explanation":["한 사람은 원의 중심 — 제자리에 있어요.","줄은 반지름 — 팽팽하게 같은 길이로 당겨요.","중심에서 같은 길이만큼 떨어진 곳을 돌면 원이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#1','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'mc','auto','원 위의 두 점을 이은 선분 ㄱㄴ, ㄷㄹ, ㅁㅂ 가운데 원의 중심을 지나는 선분은 어느 것인가요?',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":1,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"원 위의 두 점을 이은 선분 ㄱㄴ, ㄷㄹ, ㅁㅂ 가운데 원의 중심을 지나는 선분은 어느 것인가요?","options":[{"t":"선분 ㄷㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅂ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄷㄹ뿐이에요.","원의 중심에 자를 대고 자와 만나는 원 위의 두 점을 이으면 이런 선분이 돼요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,49.7,"w"],"ㄴ":[108.8,43.5,"ne"],"ㄷ":[61.7,26.4,"n"],"ㄹ":[88.3,99.6,"s"],"ㅁ":[39.7,79.5,"sw"],"ㅂ":[97.4,94.9,"se"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"그림에서 원의 지름은 어느 선분인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄴㅁ","mis":"M3-2-u3-X06"},{"t":"선분 ㅇㄹ","mis":"M3-2-u3-X07"},{"t":"지름이 없어요","mis":"M3-2-u3-X06"}],"explanation":["지름은 원 위의 두 점을 이은 선분이 원의 중심 ㅇ을 지날 때의 선분이에요.","선분 ㄴㅁ은 중심을 지나지 않고, 선분 ㅇㄹ은 반지름이에요.","지름은 선분 ㄱㄷ(또는 선분 ㄷㄱ)이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[68.2,24.6,"n"],"ㄷ":[81.8,101.4,"s"],"ㄴ":[41.2,43.5,"nw"],"ㅁ":[100.1,33.1,"ne"],"ㄹ":[112.7,73.1,"e"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㅁ"],["ㅇ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#2','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'mc','auto','원 위의 두 점을 이은 선분이 원의 중심 ㅇ을 지날 때, 이 선분을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":2,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"원 위의 두 점을 이은 선분이 원의 중심 ㅇ을 지날 때, 이 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","지름의 길이를 지름이라고 부르기도 해요."],"variant_rule":{"alt":[{"stem":"원에 지름을 그으려고 해요. 자를 어디에 먼저 대야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 아무 점","mis":"M3-2-u3-X06"},{"t":"원 밖의 한 점","mis":"M3-2-u3-X19"},{"t":"원의 맨 위쪽 점","mis":"M3-2-u3-X06"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고, 자와 만나는 원 위의 두 점을 이어요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#3','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'sa','auto','원에 지름을 여러 개 긋고 재었더니 지름 하나가 6 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"원에 지름을 여러 개 긋고 재었더니 지름 하나가 6 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 6 cm예요."],"variant_rule":{"alt":[{"stem":"「안에 알맞은 수」 — 원에 그은 지름 하나가 8 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 8 cm예요."]},{"stem":"원에 지름 3개를 긋고 재었더니 지름 하나가 3 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#4','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'mc','auto','한 원에 지름은 몇 개 그을 수 있나요?',ARRAY['M3-2-u3-X04']::text[],true,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"한 원에 지름은 몇 개 그을 수 있나요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M3-2-u3-X04"},{"t":"2개","mis":"M3-2-u3-X04"},{"t":"4개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원의 중심을 지나는 방향은 셀 수 없이 많아요.","그래서 한 원에 지름은 무수히 많아요."],"variant_rule":{"alt":[{"stem":"원에 지름을 여러 개 긋고 길이를 비교했어요. 한 원에서 지름의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"그은 방향마다 달라요","mis":"M3-2-u3-X05"},{"t":"가로로 그은 것이 가장 길어요","mis":"M3-2-u3-X05"},{"t":"알 수 없어요","mis":"M3-2-u3-X05"}],"explanation":["지름은 모두 원의 중심을 지나 원 위의 두 점을 이어요.","재어 보면 길이가 모두 같아요.","한 원에서 지름은 모두 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#5','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',2,'mc','auto','지름을 옳게 표시한 것은 어느 것인가요?',ARRAY['M3-2-u3-X18','M3-2-u3-X19','M3-2-u3-X06']::text[],true,'{"seq":5,"concept":"M3-2-u3-C3","difficulty":2,"kind":"mc","stem":"지름을 옳게 표시한 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M3-2-u3-X18"},{"t":"㉯","mis":"M3-2-u3-X19"},{"t":"셋 모두 지름이에요","mis":"M3-2-u3-X06"}],"explanation":["지름은 원 위의 두 점을 이은 선분이 원의 중심을 지날 때의 선분이에요.","꺾인 선(반지름 두 개)이나 원 밖까지 뻗은 선은 지름이 아니에요.","㉰만 원 위의 두 점을 곧게 잇고 원의 중심을 지나요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"pts":{"ㄱ":[18.0,26.1,"nw"],"ㅇ":[45,45,"s"],"ㄴ":[72.0,26.1,"ne"]},"circle":[[[45,45],33.0]],"seg":[["ㄱ","ㅇ"],["ㅇ","ㄴ"]]},{"w":90,"h":90,"pts":{"ㄱ":[3.0,33.7,"n"],"ㅇ":[45,45,"n"],"ㄴ":[87.0,56.3,"s"]},"circle":[[[45,45],33.0]],"seg":[["ㄱ","ㄴ"]]},{"w":90,"h":90,"pts":{"ㄱ":[31.1,15.1,"nw"],"ㅇ":[45,45,"sw"],"ㄴ":[58.9,74.9,"se"]},"circle":[[[45,45],33.0]],"seg":[["ㄱ","ㄴ"]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 지름을 옳게 표시한 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u3-X18"},{"t":"㉰","mis":"M3-2-u3-X19"},{"t":"셋 모두 지름이에요","mis":"M3-2-u3-X06"}],"explanation":["지름은 원 위의 두 점을 이은 선분이 원의 중심을 지날 때의 선분이에요.","꺾인 선(반지름 두 개)이나 원 밖까지 뻗은 선은 지름이 아니에요.","㉮만 원 위의 두 점을 곧게 잇고 원의 중심을 지나요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"pts":{"ㄱ":[31.1,15.1,"nw"],"ㅇ":[45,45,"sw"],"ㄴ":[58.9,74.9,"se"]},"circle":[[[45,45],33.0]],"seg":[["ㄱ","ㄴ"]]},{"w":90,"h":90,"pts":{"ㄱ":[18.0,26.1,"nw"],"ㅇ":[45,45,"s"],"ㄴ":[72.0,26.1,"ne"]},"circle":[[[45,45],33.0]],"seg":[["ㄱ","ㅇ"],["ㅇ","ㄴ"]]},{"w":90,"h":90,"pts":{"ㄱ":[3.0,33.7,"n"],"ㅇ":[45,45,"n"],"ㄴ":[87.0,56.3,"s"]},"circle":[[[45,45],33.0]],"seg":[["ㄱ","ㄴ"]]}]}},{"stem":"이번에는 다른 그림이에요. 지름을 옳게 표시한 것은 어느 것인가요?","options":[{