]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#9','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',2,'mc','auto','「연결」 — 시계 모양의 원에 원의 중심과 지름을 표시하려고 해요. 원의 중심은 어디인가요?',ARRAY['M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":9,"concept":"M3-2-u3-C3","difficulty":2,"kind":"mc","stem":"「연결」 — 시계 모양의 원에 원의 중심과 지름을 표시하려고 해요. 원의 중심은 어디인가요?","options":[{"t":"시곗바늘이 돌아가는 가운데 점","correct":true},{"t":"숫자 12가 있는 곳","mis":"M3-2-u3-X03"},{"t":"시계 테두리 위의 한 점","mis":"M3-2-u3-X02"},{"t":"숫자 3과 9 사이의 아무 곳","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원의 가장 안쪽에 있는 한 점이에요.","시계에서는 시곗바늘이 돌아가는 가운데 점이에요.","원의 중심을 먼저 찾아야 반지름과 지름을 표시할 수 있어요."],"variant_rule":{"alt":[{"stem":"「연결」 — 시계에서 12와 6을 잇는 선분은 시곗바늘이 돌아가는 가운데를 지나요. 이 선분은 시계 모양 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["12와 6은 시계 테두리(원) 위에 있어요.","두 점을 이은 선분이 원의 중심을 지나요.","그래서 지름이에요."]},{"stem":"「연결」 — 모눈 위에 놓인 레몬 조각(원 모양)에 지름을 표시하려고 해요. 어떻게 그어야 하나요?","options":[{"t":"레몬 조각의 중심을 지나고 테두리 위의 두 점을 잇는 선분을 그어요","correct":true},{"t":"레몬 조각의 중심에서 테두리까지 선분을 그어요","mis":"M3-2-u3-X07"},{"t":"테두리 위의 아무 두 점이나 이어요","mis":"M3-2-u3-X06"},{"t":"중심을 지나 레몬 조각 밖까지 길게 그어요","mis":"M3-2-u3-X19"}],"explanation":["지름의 두 끝은 원 위의 점이에요.","그리고 원의 중심을 지나야 해요.","중심에서 테두리까지만 그으면 반지름이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_basic#10','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',3,'ox','auto','「원 위의 두 점을 이은 선분은 모두 원의 지름이에요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":10,"concept":"M3-2-u3-C3","difficulty":3,"kind":"ox","stem":"「원 위의 두 점을 이은 선분은 모두 원의 지름이에요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"원의 중심을 지나는 선분만 지름이라서","correct":true},{"t":"원 위의 두 점을 이으면 모두 지름이라서","mis":"M3-2-u3-X06"}],"mis":"M3-2-u3-X06","explanation":["원 위의 두 점을 이어도 원의 중심을 지나지 않는 선분이 많아요.","원의 중심을 지나는 선분만 지름이에요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"나은이는 「한 원에 지름은 1개입니다.」라고 말했어요. 나은이의 말이 맞나요?","answer":"X","reason_options":[{"t":"원의 중심을 지나는 선분은 무수히 많이 그을 수 있어서","correct":true},{"t":"원의 중심이 하나라서 지름도 하나뿐이라서","mis":"M3-2-u3-X04"}],"explanation":["원의 중심을 지나 원 위의 두 점을 잇는 선분은 방향마다 그을 수 있어요.","한 원에 지름은 무수히 많아요.","나은이의 말은 틀렸어요(X)."]},{"stem":"「원의 중심을 지나도록 원 밖까지 길게 그은 선도 지름이에요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"지름의 두 끝은 원 위의 점이어야 해서","correct":true},{"t":"원의 중심만 지나면 모두 지름이라서","mis":"M3-2-u3-X19"}],"explanation":["지름은 원 위의 두 점을 이은 선분이에요.","원 밖까지 뻗은 선은 두 끝이 원 위에 있지 않아요.","이 말은 틀렸어요(X)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#1','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',2,'error','auto','「확인 문제」 — 원에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X16']::text[],true,'{"seq":1,"concept":"M3-2-u3-C3","difficulty":2,"kind":"error","stem":"「확인 문제」 — 원에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"나은 — 「한 원에 지름은 1개입니다.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「한 원에서 지름은 모두 같아.」","mis":"M3-2-u3-X16"}],"explanation":["한 원에 원의 중심은 1개, 반지름과 지름은 무수히 많아요.","지름은 원의 중심을 지나는 방향마다 그을 수 있어요.","나은이의 말이 잘못이에요."],"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 — 원에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"서준 — 「한 원에 지름은 한 개 그을 수 있어.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「한 원에서 지름은 모두 같아.」","mis":"M3-2-u3-X16"}],"explanation":["한 원에 지름은 무수히 많이 그을 수 있어요.","나머지 세 사람의 말은 맞아요.","서준이의 말이 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#2','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',2,'mc','auto','선분 네 개 가운데 지름이 아닌 것은 어느 것인가요? 원의 중심 ㅇ을 잘 보세요.',ARRAY['M3-2-u3-X16']::text[],true,'{"seq":2,"concept":"M3-2-u3-C3","difficulty":2,"kind":"mc","stem":"선분 네 개 가운데 지름이 아닌 것은 어느 것인가요? 원의 중심 ㅇ을 잘 보세요.","options":[{"t":"선분 ㄴㅂ","correct":true},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X16"},{"t":"선분 ㄷㅅ","mis":"M3-2-u3-X16"},{"t":"선분 ㄹㅈ","mis":"M3-2-u3-X16"}],"explanation":["선분 ㄴㅂ은 원의 중심 가까이를 지나지만 중심을 지나지는 않아요.","선분 ㄱㅁ, ㄷㅅ, ㄹㅈ은 원의 중심 ㅇ을 지나요.","눈으로 보기 어려우면 원의 중심에 자를 대어 확인해요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㅁ":[85.1,100.7,"s"],"ㅈ":[97.4,31.1,"ne"],"ㄹ":[52.6,94.9,"sw"],"ㄷ":[36.1,66.4,"w"],"ㅅ":[113.9,59.6,"e"],"ㄴ":[41.9,42.3,"nw"],"ㅂ":[112.1,75.1,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅁ"],["ㅈ","ㄹ"],["ㄷ","ㅅ"],["ㄴ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"「추론」 — 지름을 나타내는 선분을 모두 고른 것은 어느 것인가요?","options":[{"t":"선분 ㄱㅁ, 선분 ㄷㅅ, 선분 ㄹㅈ","correct":true},{"t":"선분 ㄱㅁ, 선분 ㄴㅂ, 선분 ㄷㅅ, 선분 ㄹㅈ","mis":"M3-2-u3-X06"},{"t":"선분 ㄱㅁ, 선분 ㄴㅂ","mis":"M3-2-u3-X06"},{"t":"선분 ㄷㅅ","mis":"M3-2-u3-X04"}],"explanation":["원의 중심 ㅇ을 지나는 선분만 지름이에요.","선분 ㄴㅂ은 중심 가까이를 지나지만 중심을 지나지 않아요.","지름은 선분 ㄱㅁ, ㄷㅅ, ㄹㅈ — 재어 보면 길이도 모두 같아요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㅁ":[85.1,100.7,"s"],"ㅈ":[97.4,31.1,"ne"],"ㄹ":[52.6,94.9,"sw"],"ㄷ":[36.1,66.4,"w"],"ㅅ":[113.9,59.6,"e"],"ㄴ":[41.9,42.3,"nw"],"ㅂ":[112.1,75.1,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅁ"],["ㅈ","ㄹ"],["ㄷ","ㅅ"],["ㄴ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLU