INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#3','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',3,'match','auto','「빈칸을 채우세요」 — 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":3,"kind":"match","stem":"「빈칸을 채우세요」 — 알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심","r":"원을 그릴 때 누름 못이 꽂힌 점"},{"l":"반지름","r":"원의 중심과 원 위의 한 점을 이은 선분"},{"l":"지름","r":"원 위의 두 점을 이은 선분이 원의 중심을 지날 때 그 선분"}],"mis":"M3-2-u3-X07","explanation":["원의 중심: 누름 못이 꽂힌 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","지름: 원의 중심을 지나 원 위의 두 점을 이은 선분."],"variant_rule":{"alt":[{"stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심","r":"원의 가장 안쪽에 있는 한 점"},{"l":"반지름","r":"지름의 반"},{"l":"지름","r":"원 위의 두 점을 이은 선분 중 가장 긴 선분"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점.","반지름은 지름의 반.","지름은 원 위의 두 점을 이은 선분 중 가장 긴 선분."]},{"stem":"컴퍼스로 원을 그리는 것과 알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심","r":"컴퍼스의 침을 꽂는 점"},{"l":"반지름","r":"컴퍼스의 침과 연필 끝 사이의 거리"},{"l":"지름","r":"원을 똑같이 둘로 나누는 선분"}],"explanation":["침을 꽂는 점이 원의 중심.","침과 연필 끝 사이 거리가 반지름.","원을 똑같이 둘로 나누는 선분이 지름."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#4','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C2',3,'mc','auto','「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?',ARRAY['M3-2-u3-X20','M3-2-u3-X08']::text[],true,'{"seq":4,"concept":"M3-2-u3-C2","difficulty":3,"kind":"mc","stem":"「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?","options":[{"t":"4 cm","correct":true},{"t":"6 cm","mis":"M3-2-u3-X20"},{"t":"5 cm","mis":"M3-2-u3-X20"},{"t":"8 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이은 선분이에요.","원의 중심과 이어지지 않은 선분(6 cm, 5 cm)은 반지름이 아니에요.","중심에서 그은 선분이 4 cm — 반지름은 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[49.9,33.1,"nw"],"ㄴ":[100.1,33.1,"ne"],"ㄷ":[81.8,101.4,"s"],"ㄹ":[113.9,65.0,"e"],"ㅁ":[37.3,52.9,"w"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅇ","ㅁ"]],"lab":[[[75.0,12.8],"6 cm"],[[112.6,96.3],"5 cm"],[[49.2,65.7],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?","options":[{"t":"5 cm","correct":true},{"t":"3 cm","mis":"M3-2-u3-X20"},{"t":"7 cm","mis":"M3-2-u3-X20"},{"t":"10 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이은 선분이에요.","원의 중심과 이어지지 않은 선분(3 cm, 7 cm)은 반지름이 아니에요.","중심에서 그은 선분이 5 cm — 반지름은 5 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[41.2,43.5,"nw"],"ㄴ":[52.6,31.1,"nw"],"ㄷ":[36.1,59.6,"w"],"ㄹ":[75.0,24.0,"n"],"ㅁ":[75.0,102.0,"s"],"ㅂ":[39.7,79.5,"sw"],"ㅅ":[112.7,73.1,"e"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㄴ","ㄷ"],["ㄹ","ㅁ"],["ㅂ","ㅅ"]],"lab":[[[49.4,59.0],"5 cm"],[[31.5,37.9],"3 cm"],[[79.4,113.1],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLU