INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#5','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',3,'mc','auto','「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X07']::text[],true,'{"seq":5,"concept":"M3-2-u3-C3","difficulty":3,"kind":"mc","stem":"「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?","options":[{"t":"7 cm","correct":true},{"t":"5 cm","mis":"M3-2-u3-X06"},{"t":"6 cm","mis":"M3-2-u3-X06"},{"t":"14 cm","mis":"M3-2-u3-X07"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","원의 중심을 지나지 않는 선분의 길이는 지름이 아니에요.","원의 중심을 지나는 선분이 7 cm — 지름은 7 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㄴ":[68.2,24.6,"n"],"ㄷ":[111.6,49.7,"e"],"ㄹ":[108.8,82.5,"se"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"]],"lab":[[[31.5,37.9],"5 cm"],[[87.9,47.1],"7 cm"],[[70.6,113.1],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?","options":[{"t":"12 cm","correct":true},{"t":"6 cm","mis":"M3-2-u3-X07"},{"t":"8 cm","mis":"M3-2-u3-X06"},{"t":"24 cm","mis":"M3-2-u3-X07"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","원의 중심을 지나지 않는 선분의 길이는 지름이 아니에요.","원의 중심을 지나는 선분이 12 cm — 지름은 12 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[81.8,24.6,"n"],"ㄴ":[68.2,101.4,"s"],"ㄷ":[111.6,49.7,"e"],"ㄹ":[38.4,76.3,"w"],"ㅁ":[88.3,99.6,"s"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅁ"]],"lab":[[[82.3,82.1],"12 cm"],[[94.5,46.0],"6 cm"],[[53.8,108.5],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDE