INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#6','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',3,'ox','auto','원 위의 두 점 ㄱ, ㄴ을 이은 선분 ㄱㄴ이 7 cm예요. 「그러니까 이 원의 지름은 7 cm예요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":6,"concept":"M3-2-u3-C3","difficulty":3,"kind":"ox","stem":"원 위의 두 점 ㄱ, ㄴ을 이은 선분 ㄱㄴ이 7 cm예요. 「그러니까 이 원의 지름은 7 cm예요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"선분 ㄱㄴ이 원의 중심을 지나는지 알 수 없어서","correct":true},{"t":"원 위의 두 점을 이은 선분은 지름이라서","mis":"M3-2-u3-X06"}],"mis":"M3-2-u3-X06","explanation":["원 위의 두 점을 이은 선분이 모두 지름은 아니에요.","원의 중심을 지날 때만 지름이에요.","중심을 지나는지 모르니 지름이 7 cm라고 할 수 없어요(X)."],"variant_rule":{"alt":[{"stem":"원 위의 두 점 ㄱ, ㄴ을 이은 선분 ㄱㄴ이 8 cm예요. 「그러니까 이 원의 지름은 8 cm예요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"선분 ㄱㄴ이 원의 중심을 지나는지 알 수 없어서","correct":true},{"t":"원 위의 두 점을 이은 선분은 지름이라서","mis":"M3-2-u3-X06"}],"explanation":["원 위의 두 점을 이은 선분이 모두 지름은 아니에요.","원의 중심을 지날 때만 지름이에요.","지름이 8 cm라고 할 수 없어요(X)."]},{"stem":"원 위의 두 점 ㄱ, ㄴ을 이은 선분 ㄱㄴ이 원의 중심을 지나고, 길이는 6 cm예요. 「그러니까 이 원의 지름은 6 cm예요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"원의 중심을 지나는 선분이라 지름이어서","correct":true},{"t":"원 위의 두 점을 이은 선분은 지름이 될 수 없어서","mis":"M3-2-u3-X06"}],"explanation":["선분 ㄱㄴ은 원 위의 두 점을 이었어요.","그리고 원의 중심을 지나요 — 지름이에요.","지름은 6 cm예요(O)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#7','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',3,'mc','auto','점 ㄱ에서 원의 중심 ㅇ까지 자를 대었어요. 자를 그대로 두고 선분을 늘여 원과 다시 만나는 점을 찾으면 어느 것인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X03']::text[],true,'{"seq":7,"concept":"M3-2-u3-C3","difficulty":3,"kind":"mc","stem":"점 ㄱ에서 원의 중심 ㅇ까지 자를 대었어요. 자를 그대로 두고 선분을 늘여 원과 다시 만나는 점을 찾으면 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M3-2-u3-X06"},{"t":"점 ㄹ","mis":"M3-2-u3-X06"},{"t":"점 ㅇ","mis":"M3-2-u3-X03"}],"explanation":["점 ㄱ에서 원의 중심 ㅇ을 지나 곧게 그어요.","반대쪽 원 위에서 만나는 점은 점 ㄴ이에요.","이렇게 그은 선분 ㄱㄴ이 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[41.2,82.5,"sw"],"ㄷ":[36.6,56.2,"w"],"ㄹ":[64.9,100.7,"s"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ에서 원의 중심 ㅇ까지 자를 대었어요. 자를 그대로 두고 선분을 늘여 원과 다시 만나는 점을 찾으면 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M3-2-u3-X06"},{"t":"점 ㄴ","mis":"M3-2-u3-X06"},{"t":"점 ㅇ","mis":"M3-2-u3-X03"}],"explanation":["점 ㄱ에서 원의 중심 ㅇ을 지나 곧게 그어요.","반대쪽 원 위에서 만나는 점은 점 ㄷ이에요.","이렇게 그은 선분 ㄱㄷ이 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,49.7,"w"],"ㄷ":[111.6,76.3,"e"],"ㄹ":[94.5,96.8,"se"],"ㄴ":[110.3,46.5,"ne"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅇ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ에서 원의 중심 ㅇ까지 자를 대었어요. 자를 그대로 두고 선분을 늘여 원과 다시 만나는 점을 찾으면 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X06"},{"t":"점 ㄷ","mis":"M3-2-u3-X06"},{"t":"점 ㅇ","mis":"M3-2-u3-X03"}],"explanation":["점 ㄱ에서 원의 중심 ㅇ을 지나 곧게 그어요.","반대쪽 원 위에서 만나는 점은 점 ㄹ이에요.","이렇게 그은 선분 ㄱㄹ이 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[61.7,99.6,"s"],"