INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#8','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',4,'sa','auto','「추론」 — 이 원의 지름은 3 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"「추론」 — 이 원의 지름은 3 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 3개예요.","한 원에서 지름은 모두 3 cm예요.","3 + 3 + 3 = 9(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㅁ":[85.1,100.7,"s"],"ㅈ":[97.4,31.1,"ne"],"ㄹ":[52.6,94.9,"sw"],"ㄷ":[36.1,66.4,"w"],"ㅅ":[113.9,59.6,"e"],"ㄴ":[41.9,42.3,"nw"],"ㅂ":[112.1,75.1,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅁ"],["ㅈ","ㄹ"],["ㄷ","ㅅ"],["ㄴ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원에 지름을 여러 개 그었어요. 이 원의 지름은 6 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 3개예요.","한 원에서 지름은 모두 6 cm예요.","6 + 6 + 6 = 18(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[114.0,63.0,"e"],"ㄴ":[36.0,63.0,"w"],"ㄷ":[94.5,29.2,"ne"],"ㄹ":[55.5,96.8,"sw"],"ㅁ":[55.5,29.2,"nw"],"ㅂ":[94.5,96.8,"se"],"ㅅ":[38.4,76.3,"w"],"ㅈ":[81.8,101.4,"s"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}},{"stem":"「안에 알맞은 수」 — 이 원의 지름은 8 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 2개예요.","한 원에서 지름은 모두 8 cm예요.","8 + 8 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[41.2,82.5,"sw"],"ㄷ":[75.0,24.0,"n"],"ㄹ":[75.0,102.0,"s"],"ㅁ":[49.9,33.1,"nw"],"ㅂ":[36.0,63.0,"w"],"ㅅ":[94.5,96.8,"se"],"ㅈ":[113.4,69.8,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#9','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',4,'mc','auto','「연결」 — 시계 모양의 원에서 시곗바늘이 돌아가는 가운데가 원의 중심이에요. 12와 6을 이은 선분처럼, 마주 보는 두 숫자를 이어 그을 수 있는 지름은 모두 몇 개인가요?',ARRAY['M3-2-u3-X15','M3-2-u3-X04']::text[],false,'{"seq":9,"concept":"M3-2-u3-C3","difficulty":4,"kind":"mc","stem":"「연결」 — 시계 모양의 원에서 시곗바늘이 돌아가는 가운데가 원의 중심이에요. 12와 6을 이은 선분처럼, 마주 보는 두 숫자를 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"12개","mis":"M3-2-u3-X15"},{"t":"1개","mis":"M3-2-u3-X04"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이어요.","12와 6, 1과 7, 2와 8, 3과 9, 4와 10, 5와 11 — 숫자 두 개가 한 짝이에요.","숫자 12개를 둘씩 짝 지으면 지름은 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L03_challenge#10','math',3,2,'u3','L03','tb_g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',4,'essay','teacher','「서술형」 — 원 위의 두 점을 이은 선분이 지름인지 아닌지 알아보는 방법을 쓰고, 지름이라면 그 길이가 다른 지름과 어떤지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C3","difficulty":4,"kind":"essay","stem":"「서술형」 — 원 위의 두 점을 이은 선분이 지름인지 아닌지 알아보는 방법을 쓰고, 지름이라면 그 길이가 다른 지름과 어떤지도 써 보세요.","answer_guide":{"answer":"예: 선분이 원의 중심을 지나는지 본다. 원의 중심에 자를 대어 선분이 중심을 지나면 지름이고, 지나지 않으면 지름이 아니다. 한 원에서 지름은 모두 길이가 같으므로 다른 지름과 길이가 같다.","scoring_points":["원의 중심을 지나는지 확인한다고 썼는가","지나면 지름, 아니면 지름이 아니라고 구별했는가","한 원에서 지름은 모두 같다고 썼는가"]},"explanation":["지름의 조건: 원 위의 두 점 + 원의 중심을 지남.","원의 중심에 자를 대어 확인해요.","한 원의 지름은 모두 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#1','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',1,'sa','auto','「안에 알맞은 수」 — 반지름이 4 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"「안에 알맞은 수」 — 반지름이 4 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에서 지름은 반지름의 2배예요.","4 cm의 2배를 구해요.","4 × 2 = 8 — 지름은 8 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 원에서 지름은 반지름의 2배예요.","8 cm의 2배를 구해요.","8 × 2 = 16 — 지름은 16 cm예요."]},{"stem":"「스스로 마무리하기」 — 반지름이 7 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["한 원에서 지름은 반지름의 2배예요.","7 cm의 2배를 구해요.","7 × 2 = 14 — 지름은 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#2','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',1,'sa','auto','「안에 알맞은 수」 — 지름이 10 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"「안에 알맞은 수」 — 지름이 10 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 원에서 반지름은 지름의 반이에요.","10 cm를 똑같이 둘로 나눠요.","10의 반은 5 — 반지름은 5 cm예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 지름이 8 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 원에서 반지름은 지름의 반이에요.","8 cm를 똑같이 둘로 나눠요.","8의 반은 4 — 반지름은 4 cm예요."]},{"stem":"「스스로 마무리하기」 — 지름이 12 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에서 반지름은 지름의 반이에요.","12 cm를 똑같이 둘로 나눠요.","12의 반은 6 — 반지름은 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#3','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',1,'mc','auto','원 모양의 종이가 똑같이 둘로 나누어지도록 접었다 폈어요. 접었다 폈을 때 생기는 선분은 원의 무엇인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":3,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"원 모양의 종이가 똑같이 둘로 나누어지도록 접었다 폈어요. 접었다 폈을 때 생기는 선분은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["똑같이 둘로 접으면 접힌 선이 원의 중심 ㅇ을 지나요.","접힌 선은 원 위의 두 점을 이은 선분이면서 원의 중심을 지나요.","그래서 원의 지름이에요 — 지름은 원을 똑같이 둘로 나눠요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 원을 똑같이 둘로 나누는 선분은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 두 점을 이은 아무 선분","mis":"M3-2-u3-X06"},{"t":"원의 중심","mis":"M3-2-u3-X21"}],"explanation":["원을 똑같이 둘로 나누는 선분은 원의 중심을 지나요.","그 선분은 원 위의 두 점을 이어요.","그래서 지름이에요 — 원의 중심(점)이 나누는 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#4','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',1,'mc','auto','선분 ㄱㄴ, 선분 ㄱㄷ, 선분 ㄱㄹ, 선분 ㄱㅁ 가운데 길이가 가장 긴 선분은 어느 것인가요?',ARRAY['M3-2-u3-X17']::text[],true,'{"seq":4,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"선분 ㄱㄴ, 선분 ㄱㄷ, 선분 ㄱㄹ, 선분 ㄱㅁ 가운데 길이가 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","그중 원의 중심 ㅇ을 지나는 선분 ㄱㄹ이 지름이에요.","원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,49.7,"w"],"ㄴ":[68.2,24.6,"n"],"ㄷ":[94.5,29.2,"ne"],"ㄹ":[111.6,76.3,"e"],"ㅁ":[68.2,101.4,"s"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㄱ에서 그은 선분 가운데 길이가 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄹ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","그중 원의 중심 ㅇ을 지나는 선분 ㄱㄷ이 지름이에요.","원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[61.7,26.4,"n"],"ㄷ":[41.2,82.5,"sw"],"ㄹ":[68.2,101.4,"s"],"ㅁ":[104.9,88.1,"se"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#5','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'mc','auto','드림캐처에 그어진 지름과 반지름을 재었더니 작은 드림캐처는 지름 2 cm, 반지름 1 cm이고, 큰 드림캐처는 지름 4 cm, 반지름 2 cm였어요. 한 원에서 지름은 반지름의 몇 배인가요?',ARRAY['M3-2-u3-X08','M3-2-u3-X09']::text[],true,'{"seq":5,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"드림캐처에 그어진 지름과 반지름을 재었더니 작은 드림캐처는 지름 2 cm, 반지름 1 cm이고, 큰 드림캐처는 지름 4 cm, 반지름 2 cm였어요. 한 원에서 지름은 반지름의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"반","mis":"M3-2-u3-X08"},{"t":"1배(길이가 같아요)","mis":"M3-2-u3-X09"},{"t":"3배","mis":"M3-2-u3-X09"}],"explanation":["1 × 2 = 2, 2 × 2 = 4예요.","지름은 반지름 두 개를 이은 것과 같아요.","한 원에서 지름은 반지름의 2배예요."],"variant_rule":{"alt":[{"stem":"원 가는 반지름 1 cm, 지름 2 cm이고, 원 나는 반지름 2 cm, 지름 4 cm예요. 한 원에서 반지름은 지름의 얼마인가요?","options":[{"t":"반","correct":true},{"t":"2배","mis":"M3-2-u3-X08"},{"t":"같아요","mis":"M3-2-u3-X09"},{"t":"3배","mis":"M3-2-u3-X08"}],"explanation":["2의 반은 1, 4의 반은 2예요.","반지름은 지름을 똑같이 둘로 나눈 것이에요.","한 원에서 반지름은 지름의 반이에요 — 그래서 이름이 「반지름」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#6','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'sa','auto','점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["선분 ㅇㄱ은 반지름 — 5 cm예요.","한 원에서 지름은 반지름의 2배예요.","5 × 2 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[111.6,49.7,"e"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[94.5,46.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ은 반지름 — 3 cm예요.","한 원에서 지름은 반지름의 2배예요.","3 × 2 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[61.7,26.4,"n"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[58.0,43.5],"3 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["선분 ㅇㄱ은 반지름 — 7 cm예요.","한 원에서 지름은 반지름의 2배예요.","7 × 2 = 14(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㅇ":[75,63.0,"ne"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[55.5,80.0],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#7','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'sa','auto','선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분 ㄱㄴ은 지름 — 8 cm예요.","선분 ㅇㄷ은 반지름이고, 반지름은 지름의 반이에요.","8의 반 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[41.2,82.5,"sw"],"ㄷ":[45.1,37.9,"nw"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[100.7,64.6],"8 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["선분 ㄱㄴ은 지름 — 10 cm예요.","선분 ㅇㄷ은 반지름이고, 반지름은 지름의 반이에요.","10의 반 — 5 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[41.2,43.5,"nw"],"ㄴ":[108.8,82.5,"se"],"ㄷ":[68.2,101.4,"s"],"ㅇ":[75,63.0,"ne"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[63.5,39.9],"10 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㄱㄴ은 지름 — 12 cm예요.","선분 ㅇㄷ은 반지름이고, 반지름은 지름의 반이에요.","12의 반 — 6 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[81.8,24.6,"n"],"ㄴ":[68.2,101.4,"s"],"ㄷ":[36.6,69.8,"w"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[92.8,44.4],"12 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#8','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'mc','auto','「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 4 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],true,'{"seq":8,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 4 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 8 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 16 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 4 cm인 원의 지름은 4 × 2 = 8(cm)예요.","그래서 「지름이 8 cm인 원」 카드와 짝이에요."],"variant_rule":{"alt":[{"stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 5 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 10 cm인 원","correct":true},{"t":"지름이 5 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 10 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 20 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 5 cm인 원의 지름은 5 × 2 = 10(cm)예요.","그래서 「지름이 10 cm인 원」 카드와 짝이에요."]},{"stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 3 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 6 cm인 원","correct":true},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 6 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 12 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 3 cm인 원의 지름은 3 × 2 = 6(cm)예요.","그래서 「지름이 6 cm인 원」 카드와 짝이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#9','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',2,'mc','auto','「크기가 가장 큰 원」 — 크기가 가장 큰 원을 찾아 기호를 쓰세요. (㉠ 반지름이 5 cm인 원, ㉡ 반지름이 6 cm인 원, ㉢ 지름이 10 cm인 원)',ARRAY['M3-2-u3-X10','M3-2-u3-X09']::text[],true,'{"seq":9,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"「크기가 가장 큰 원」 — 크기가 가장 큰 원을 찾아 기호를 쓰세요. (㉠ 반지름이 5 cm인 원, ㉡ 반지름이 6 cm인 원, ㉢ 지름이 10 cm인 원)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X10"},{"t":"모두 같아요","mis":"M3-2-u3-X09"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 10 cm, ㉡ 지름 12 cm, ㉢ 지름 10 cm.","크기가 가장 큰 원은 ㉡이에요 — 적힌 수만 보면 안 돼요."],"variant_rule":{"alt":[{"stem":"크기가 가장 작은 원을 찾아 기호를 쓰세요. (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉡","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 8 cm, ㉢ 지름 12 cm, ㉣ 지름 4 cm.","크기가 가장 작은 원은 ㉣이에요 — 적힌 수만 보면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_basic#10','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',3,'ox','auto','「반지름이 5 cm인 원과 지름이 10 cm인 원은 크기가 같아요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X10']::text[],true,'{"seq":10,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"「반지름이 5 cm인 원과 지름이 10 cm인 원은 크기가 같아요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름 5 cm인 원의 지름도 10 cm라서","correct":true},{"t":"적힌 수가 달라서 크기도 달라서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["반지름 5 cm인 원의 지름은 5 × 2 = 10(cm)예요.","두 원의 지름이 모두 10 cm예요.","크기가 같아요(O) — 수만 보고 견주면 안 돼요."],"variant_rule":{"alt":[{"stem":"「지름이 4 cm인 원과 반지름이 4 cm인 원은 크기가 같아요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"반지름이 4 cm인 원은 지름이 8 cm라서","correct":true},{"t":"적힌 수가 같으면 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 4 cm인 원의 지름은 4 × 2 = 8(cm)예요.","지름 4 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."]},{"stem":"「지름이 6 cm인 원과 반지름이 3 cm인 원은 크기가 같아요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름 3 cm인 원의 지름이 6 cm라서","correct":true},{"t":"적힌 수가 달라서 크기도 달라서","mis":"M3-2-u3-X10"}],"explanation":["반지름 3 cm인 원의 지름은 3 × 2 = 6(cm)예요.","두 원 모두 지름이 6 cm예요.","크기가 같아요(O)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#1','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C4',2,'match','auto','「크기가 같은 원끼리」 — 크기가 같은 원끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u3-C4","difficulty":2,"kind":"match","stem":"「크기가 같은 원끼리」 — 크기가 같은 원끼리 이으세요.","pairs":[{"l":"지름이 4 cm인 원","r":"반지름이 2 cm인 원"},{"l":"지름이 6 cm인 원","r":"반지름이 3 cm인 원"},{"l":"지름이 2 cm인 원","r":"원을 똑같이 둘로 나누는 선분의 길이가 2 cm인 원"}],"mis":"M3-2-u3-X08","explanation":["지름은 반지름의 2배예요 — 반지름 2 cm면 지름 4 cm, 3 cm면 6 cm.","원을 똑같이 둘로 나누는 선분은 지름이에요.","같은 지름끼리 이으면 크기가 같은 원이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「크기가 같은 원끼리」 — 크기가 같은 원끼리 이으세요.","pairs":[{"l":"반지름이 2 cm인 원","r":"원 위의 두 점을 이은 선분 중에서 가장 긴 선분의 길이가 4 cm인 원"},{"l":"반지름이 3 cm인 원","r":"원을 똑같이 둘로 나누는 선분의 길이가 6 cm인 원"},{"l":"지름이 2 cm인 원","r":"원 위의 두 점을 이은 선분 중에서 가장 긴 선분의 길이가 2 cm인 원"}],"explanation":["가장 긴 선분과 원을 똑같이 둘로 나누는 선분은 모두 지름이에요.","반지름 2 cm → 지름 4 cm, 반지름 3 cm → 지름 6 cm.","지름이 같으면 크기가 같은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#2','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',2,'mc','auto','원에 대해 바르게 설명한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X17','M3-2-u3-X21']::text[],true,'{"seq":2,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"원에 대해 바르게 설명한 사람은 누구인가요?","options":[{"t":"서윤 — 「반지름은 지름의 반이야.」","correct":true},{"t":"정후 — 「원을 똑같이 둘로 나눌 수 있는 선분은 1개야.」","mis":"M3-2-u3-X04"},{"t":"현수 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 반지름이야.」","mis":"M3-2-u3-X17"},{"t":"지유 — 「원의 중심은 원을 똑같이 둘로 나눠.」","mis":"M3-2-u3-X21"}],"explanation":["원을 똑같이 둘로 나누는 선분은 지름 — 무수히 많아요.","가장 긴 선분은 반지름이 아니라 지름이고, 원을 둘로 나누는 것도 지름이에요.","바르게 설명한 사람은 서윤이에요."],"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 — 원에 대해 바르게 설명한 사람은 누구인가요?","options":[{"t":"은비 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 원의 지름이야.」","correct":true},{"t":"서준 — 「한 원에 지름은 한 개 그을 수 있어.」","mis":"M3-2-u3-X04"},{"t":"지유 — 「원의 중심은 원을 똑같이 둘로 나눠.」","mis":"M3-2-u3-X21"},{"t":"건우 — 「한 원에 반지름은 2개 그을 수 있어.」","mis":"M3-2-u3-X04"}],"explanation":["한 원에 지름·반지름은 무수히 많아요.","원을 똑같이 둘로 나누는 것은 원의 중심이 아니라 지름이에요.","바르게 설명한 사람은 은비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#3','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',3,'mc','auto','「추론」 — 크기가 큰 원부터 차례대로 기호를 쓴 것은 어느 것인가요? (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)',ARRAY['M3-2-u3-X10','M3-2-u3-X16']::text[],false,'{"seq":3,"concept":"M3-2-u3-C5","difficulty":3,"kind":"mc","stem":"「추론」 — 크기가 큰 원부터 차례대로 기호를 쓴 것은 어느 것인가요? (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)","options":[{"t":"㉢, ㉡, ㉠, ㉣","correct":true},{"t":"㉠, ㉢, ㉡, ㉣","mis":"M3-2-u3-X10"},{"t":"㉣, ㉠, ㉡, ㉢","mis":"M3-2-u3-X16"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M3-2-u3-X10"}],"explanation":["크기가 큰 원은 지름(반지름)이 긴 원이에요 — 모두 지름으로 바꾸어요.","㉠ 6 cm, ㉡ 8 cm, ㉢ 12 cm, ㉣ 4 cm.","큰 것부터 ㉢, ㉡, ㉠, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#4','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C8',3,'sa','auto','「문제 해결」 — 원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 눈사람의 맨 위에서 맨 아래까지 두 원의 중심을 지나게 그은 선분의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C8","difficulty":3,"kind":"sa","stem":"「문제 해결」 — 원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 눈사람의 맨 위에서 맨 아래까지 두 원의 중심을 지나게 그은 선분의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["선분 위에는 작은 원의 지름과 큰 원의 지름이 이어져 있어요.","작은 원의 지름 2 × 2 = 4(cm), 큰 원의 지름 5 × 2 = 10(cm).","4 + 10 = 14(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":141.0,"circle":[[[52.5,33.0],15.0],[[52.5,85.5],37.5]],"pts":{"ㄱ":[52.5,33.0,"e"],"ㄴ":[52.5,85.5,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["선분 ㄱㄴ은 작은 원의 반지름과 큰 원의 반지름을 이은 것이에요.","작은 원 2 cm + 큰 원 5 cm.","2 + 5 = 7(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":141.0,"circle":[[[52.5,33.0],15.0],[[52.5,85.5],37.5]],"pts":{"ㄱ":[52.5,33.0,"e"],"ㄴ":[52.5,85.5,"e"]}}],"tag":false}},{"stem":"작은 드림캐처(반지름 1 cm)와 큰 드림캐처(반지름 2 cm)를 위아래로 맞닿게 매달았어요. 위 드림캐처의 맨 위에서 아래 드림캐처의 맨 아래까지 두 원의 중심을 지나는 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["두 드림캐처의 지름이 위아래로 이어져 있어요.","작은 것 1 × 2 = 2(cm), 큰 것 2 × 2 = 4(cm).","2 + 4 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":81.0,"circle":[[[52.5,25.5],7.5],[[52.5,48.0],15.0]],"pts":{"ㄱ":[52.5,25.5,"e"],"ㄴ":[52.5,48.0,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#5','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',3,'mc','auto','점 ㅇ은 원의 중심이에요. 그림의 선분은 원 위의 두 점을 이은 8 cm, 6 cm 선분과 반지름 7 cm예요. 이 원에서 원 위의 두 점을 이은 선분 가운데 가장 긴 선분은 몇 cm인가요?',ARRAY['M3-2-u3-X17','M3-2-u3-X09','M3-2-u3-X15']::text[],false,'{"seq":5,"concept":"M3-2-u3-C5","difficulty":3,"kind":"mc","stem":"점 ㅇ은 원의 중심이에요. 그림의 선분은 원 위의 두 점을 이은 8 cm, 6 cm 선분과 반지름 7 cm예요. 이 원에서 원 위의 두 점을 이은 선분 가운데 가장 긴 선분은 몇 cm인가요?","options":[{"t":"14 cm","correct":true},{"t":"8 cm","mis":"M3-2-u3-X17"},{"t":"7 cm","mis":"M3-2-u3-X09"},{"t":"15 cm","mis":"M3-2-u3-X15"}],"explanation":["원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요.","지름은 반지름의 2배 — 7 × 2 = 14(cm)예요.","8 cm 선분은 원의 중심을 지나지 않아 지름보다 짧아요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㄴ":[37.3,52.9,"w"],"ㄷ":[113.9,59.6,"e"],"ㄹ":[49.9,92.9,"sw"],"ㅁ":[85.1,100.7,"s"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅁ"]],"lab":[[[39.5,27.5],"8 cm"],[[98.3,51.6],"7 cm"],[[64.1,112.1],"6 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#6','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C4',3,'sa','auto','점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C4","difficulty":3,"kind":"sa","stem":"점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["선분 ㅇㄱ은 반지름 — 8 cm예요.","한 원에서 지름은 반지름의 2배예요.","8 × 2 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[104.9,37.9,"ne"],"ㅇ":[75,63.0,"sw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[87.5,40.3],"8 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["선분 ㅇㄱ은 반지름 — 7 cm예요.","한 원에서 지름은 반지름의 2배예요.","7 × 2 = 14(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[41.2,43.5,"nw"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[49.4,59.0],"7 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["선분 ㅇㄱ은 반지름 — 6 cm예요.","한 원에서 지름은 반지름의 2배예요.","6 × 2 = 12(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[68.2,101.4,"s"],"ㅇ":[75,63.0,"n"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[80.0,88.4],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#7','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',3,'ox','auto','현수는 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 반지름이야.」라고 말했어요. 현수의 말이 맞나요?',ARRAY['M3-2-u3-X17']::text[],true,'{"seq":7,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"현수는 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 반지름이야.」라고 말했어요. 현수의 말이 맞나요?","answer":"X","reason_options":[{"t":"가장 긴 선분은 원의 중심을 지나는 지름이라서","correct":true},{"t":"반지름은 원의 중심에서 시작해 가장 길어서","mis":"M3-2-u3-X17"}],"mis":"M3-2-u3-X17","explanation":["원 위의 두 점을 이은 선분 중 원의 중심을 지나는 것이 지름이에요.","지름은 반지름의 2배로, 원 안에서 가장 긴 선분이에요.","현수의 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"「지름은 원을 똑같이 둘로 나눠요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"원 모양 종이를 똑같이 둘로 접으면 접힌 선이 지름이라서","correct":true},{"t":"원 위의 두 점을 이은 선분은 모두 원을 똑같이 나눠서","mis":"M3-2-u3-X06"}],"explanation":["원 모양 종이를 똑같이 둘로 접었다 펴면 접힌 선이 생겨요.","그 선분은 원의 중심을 지나는 지름이에요.","맞는 말이에요(O)."]},{"stem":"지유는 「원의 중심은 원을 똑같이 둘로 나눠.」라고 말했어요. 지유의 말이 맞나요?","answer":"X","reason_options":[{"t":"원을 똑같이 둘로 나누는 것은 지름(선분)이라서","correct":true},{"t":"원의 중심은 가운데 있으니 원을 나눠서","mis":"M3-2-u3-X21"}],"explanation":["원의 중심은 점이에요.","원을 똑같이 둘로 나누는 것은 원의 중심을 지나는 지름이에요.","지유의 말은 틀렸어요(X)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#8','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',4,'mc','auto','「어느 원이 더 클까요?」 — 가와 나의 가운데에 주황색 원이 있어요. 가는 큰 원들로, 나는 작은 원들로 둘러싸여 있어서 나의 주황색 원이 더 커 보여요. 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u3-X22']::text[],false,'{"seq":8,"concept":"M3-2-u3-C5","difficulty":4,"kind":"mc","stem":"「어느 원이 더 클까요?」 — 가와 나의 가운데에 주황색 원이 있어요. 가는 큰 원들로, 나는 작은 원들로 둘러싸여 있어서 나의 주황색 원이 더 커 보여요. 알맞은 것은 어느 것인가요?","options":[{"t":"두 주황색 원의 지름을 재어 보면 같아요","correct":true},{"t":"나의 주황색 원이 더 커요","mis":"M3-2-u3-X22"},{"t":"가의 주황색 원이 더 커요","mis":"M3-2-u3-X22"},{"t":"둘러싼 원이 작을수록 가운데 원도 실제로 작아요","mis":"M3-2-u3-X22"}],"explanation":["둘레에 놓인 원의 크기 때문에 눈이 속는 것을 착시라고 해요.","실제로 두 주황색 원의 지름을 재어 보면 길이가 같아요.","원의 크기는 눈대중이 아니라 지름(반지름)을 재어 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#9','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C4',4,'sa','auto','반지름이 4 cm인 원과 지름이 4 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때, 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C4","difficulty":4,"kind":"sa","stem":"반지름이 4 cm인 원과 지름이 4 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때, 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["반지름 4 cm인 원의 지름은 4 × 2 = 8(cm)예요.","다른 원의 지름은 4 cm 그대로예요.","8 + 4 = 12(cm)예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원과 지름이 6 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때, 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["반지름 6 cm인 원의 지름은 6 × 2 = 12(cm)예요.","다른 원의 지름은 6 cm 그대로예요.","12 + 6 = 18(cm)예요."]},{"stem":"반지름이 5 cm인 원과 지름이 10 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때, 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["반지름 5 cm인 원의 지름은 5 × 2 = 10(cm)예요.","다른 원의 지름도 10 cm예요.","10 + 10 = 20(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L04_challenge#10','math',3,2,'u3','L04','tb_g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',4,'essay','teacher','「추론」 — 반지름이 5 cm인 원 ㉠과 지름이 10 cm인 원 ㉢이 있어요. 어느 원이 더 큰지 쓰고, 그렇게 생각한 까닭을 지름과 반지름의 관계를 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C5","difficulty":4,"kind":"essay","stem":"「추론」 — 반지름이 5 cm인 원 ㉠과 지름이 10 cm인 원 ㉢이 있어요. 어느 원이 더 큰지 쓰고, 그렇게 생각한 까닭을 지름과 반지름의 관계를 써서 설명해 보세요.","answer_guide":{"answer":"예: 두 원의 크기는 같다. 한 원에서 지름은 반지름의 2배이므로 ㉠의 지름은 5 × 2 = 10(cm)이다. ㉢의 지름도 10 cm이므로 두 원의 크기는 같다.","scoring_points":["두 원의 크기가 같다고 답했는가","지름은 반지름의 2배라는 관계를 썼는가","같은 기준(지름 또는 반지름)으로 바꾸어 견주었는가"]},"explanation":["지름과 반지름이 섞여 있으면 한 가지로 바꿔요.","㉠의 지름 = 5 × 2 = 10 cm.","㉢도 10 cm — 크기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#1','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'mc','auto','컴퍼스와 자를 이용하여 원을 그릴 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M3-2-u3-X12','M3-2-u3-X07']::text[],true,'{"seq":1,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스와 자를 이용하여 원을 그릴 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"원의 중심이 되는 점 ㅇ을 정해요","correct":true},{"t":"컴퍼스를 돌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"},{"t":"침을 원 위에 꽂아요","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점 ㅇ을 정해요.","② 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요.","③ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 원을 그릴 때 컴퍼스의 침은 어디에 꽂나요?","options":[{"t":"원의 중심이 되는 점 ㅇ","correct":true},{"t":"원 위의 한 점","mis":"M3-2-u3-X12"},{"t":"지름의 한 끝","mis":"M3-2-u3-X11"},{"t":"아무 곳이나","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점 ㅇ을 정해요.","② 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요.","③ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요."]},{"stem":"컴퍼스로 원을 그리는 마지막 차례는 무엇인가요?","options":[{"t":"컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요","correct":true},{"t":"원의 중심이 되는 점 ㅇ을 정해요","mis":"M3-2-u3-X12"},{"t":"컴퍼스의 침과 연필 끝을 반지름만큼 벌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"}],"explanation":["① 원의 중심이 되는 점 ㅇ을 정해요.","② 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요.","③ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#2','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'sa','auto','「컴퍼스와 자」 — 반지름이 2 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u3-C6","difficulty":1,"kind":"sa","stem":"「컴퍼스와 자」 — 반지름이 2 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["컴퍼스의 침과 연필 끝 사이의 거리가 원의 반지름이 돼요.","반지름이 2 cm이니까","2 cm만큼 벌려요."],"variant_rule":{"alt":[{"stem":"「조건에 알맞은 원」 — 반지름이 3 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["컴퍼스의 침과 연필 끝 사이의 거리가 원의 반지름이 돼요.","반지름이 3 cm이니까","3 cm만큼 벌려요."]},{"stem":"반지름이 1 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["컴퍼스의 침과 연필 끝 사이의 거리가 원의 반지름이 돼요.","반지름이 1 cm이니까","1 cm만큼 벌려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#3','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'mc','auto','컴퍼스의 침과 연필의 끝부분 사이의 거리는 원에서 어떤 부분과 같나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":3,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스의 침과 연필의 끝부분 사이의 거리는 원에서 어떤 부분과 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X11"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["컴퍼스의 침이 꽂힌 부분이 원의 중심이에요.","침과 연필 끝 사이의 거리는 원의 중심에서 원 위의 점까지의 거리예요.","그래서 반지름과 같아요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 원을 그릴 때 컴퍼스의 침이 꽂힌 부분은 원에서 어떤 부분인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["컴퍼스의 침은 움직이지 않아요.","연필 끝이 침 둘레를 돌며 원을 그려요.","침이 꽂힌 부분은 원의 중심이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#4','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'mc','auto','「확인 문제」 — 컴퍼스를 이용하여 원을 그리는 방법을 차례대로 쓴 것은 어느 것인가요? (㉠ 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요 · ㉡ 원의 중심이 되는 점 ㅇ을 정해요 · ㉢ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요)',ARRAY['M3-2-u3-X12']::text[],true,'{"seq":4,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「확인 문제」 — 컴퍼스를 이용하여 원을 그리는 방법을 차례대로 쓴 것은 어느 것인가요? (㉠ 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요 · ㉡ 원의 중심이 되는 점 ㅇ을 정해요 · ㉢ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요)","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M3-2-u3-X12"},{"t":"㉠, ㉢, ㉡","mis":"M3-2-u3-X12"},{"t":"㉡, ㉢, ㉠","mis":"M3-2-u3-X12"}],"explanation":["먼저 원의 중심이 되는 점 ㅇ을 정해요.","다음에 반지름만큼 벌리고, 마지막에 침을 꽂고 돌려요.","차례는 ㉡, ㉠, ㉢이에요."],"variant_rule":{"alt":[{"stem":"컴퍼스를 이용하여 원을 그리는 방법을 차례대로 쓴 것은 어느 것인가요? (㉠ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그려요 · ㉡ 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요 · ㉢ 원의 중심이 되는 점 ㅇ을 정해요)","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M3-2-u3-X12"},{"t":"㉠, ㉢, ㉡","mis":"M3-2-u3-X12"},{"t":"㉡, ㉠, ㉢","mis":"M3-2-u3-X12"}],"explanation":["먼저 원의 중심이 되는 점 ㅇ을 정해요.","다음에 반지름만큼 벌리고, 마지막에 침을 꽂고 돌려요.","차례는 ㉢, ㉡, ㉠이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#5','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'sa','auto','「조건에 알맞은 원」 — 지름이 4 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"「조건에 알맞은 원」 — 지름이 4 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 4 cm의 반은 2 cm예요.","2 cm만큼 벌려요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 지름이 2 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 2 cm의 반은 1 cm예요.","1 cm만큼 벌려요."]},{"stem":"지름이 8 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 8 cm의 반은 4 cm예요.","4 cm만큼 벌려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#6','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'sa','auto','「수학익힘」 — 컴퍼스의 침과 연필의 끝부분을 1 cm만큼 벌려서 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"「수학익힘」 — 컴퍼스의 침과 연필의 끝부분을 1 cm만큼 벌려서 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["벌린 길이 1 cm가 반지름이에요.","한 원에서 지름은 반지름의 2배예요.","1 × 2 = 2(cm)예요."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침과 연필의 끝부분을 2 cm만큼 벌려서 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["벌린 길이 2 cm가 반지름이에요.","한 원에서 지름은 반지름의 2배예요.","2 × 2 = 4(cm)예요."]},{"stem":"컴퍼스의 침과 연필의 끝부분을 3 cm만큼 벌려서 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["벌린 길이 3 cm가 반지름이에요.","한 원에서 지름은 반지름의 2배예요.","3 × 2 = 6(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#7','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'mc','auto','컴퍼스의 침을 자의 눈금 0에, 연필의 끝부분을 눈금 2에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08']::text[],true,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"컴퍼스의 침을 자의 눈금 0에, 연필의 끝부분을 눈금 2에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?","options":[{"t":"반지름이 2 cm인 원","correct":true},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 8 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["침에서 연필 끝까지 2 cm 벌렸어요.","벌린 길이가 반지름이에요.","반지름 2 cm(지름 4 cm)인 원이에요."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침을 자의 눈금 0에, 연필의 끝부분을 눈금 1에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?","options":[{"t":"반지름이 1 cm인 원","correct":true},{"t":"지름이 1 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 2 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["침에서 연필 끝까지 1 cm 벌렸어요.","벌린 길이가 반지름이에요.","반지름 1 cm(지름 2 cm)인 원이에요."]},{"stem":"컴퍼스의 침을 자의 눈금 0에, 연필의 끝부분을 눈금 3에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?","options":[{"t":"반지름이 3 cm인 원","correct":true},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 6 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 12 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["침에서 연필 끝까지 3 cm 벌렸어요.","벌린 길이가 반지름이에요.","반지름 3 cm(지름 6 cm)인 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#8','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'mc','auto','지름이 2 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 2 cm만큼 벌려서 그렸어요. 어떤 원이 그려지나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08','M3-2-u3-X12']::text[],true,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"지름이 2 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 2 cm만큼 벌려서 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 4 cm인 원","correct":true},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 1 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 2 cm는 반지름이 돼요.","지름은 반지름의 2배 — 4 cm예요.","지름 2 cm인 원을 그리려면 1 cm만큼만 벌려야 해요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 4 cm만큼 벌려서 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 4 cm는 반지름이 돼요.","지름은 반지름의 2배 — 8 cm예요.","지름 4 cm인 원을 그리려면 2 cm만큼만 벌려야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#9','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'mc','auto','컴퍼스를 이용하여 주어진 원과 크기가 같은 원을 그리려고 해요. 어떻게 해야 하나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X12']::text[],true,'{"seq":9,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"컴퍼스를 이용하여 주어진 원과 크기가 같은 원을 그리려고 해요. 어떻게 해야 하나요?","options":[{"t":"주어진 원의 반지름을 재어 그만큼 컴퍼스를 벌려 그려요","correct":true},{"t":"주어진 원의 지름만큼 컴퍼스를 벌려 그려요","mis":"M3-2-u3-X11"},{"t":"컴퍼스를 아무만큼 벌려 그려요","mis":"M3-2-u3-X12"},{"t":"원의 중심을 정하지 않고 바로 돌려요","mis":"M3-2-u3-X12"}],"explanation":["크기가 같은 원은 반지름이 같아요.","주어진 원의 중심과 원 위의 한 점 사이를 재어 반지름을 알아요.","그 길이만큼 컴퍼스를 벌려 그려요."],"variant_rule":{"alt":[{"stem":"컴퍼스를 이용하여 주어진 선분을 반지름으로 하는 원을 그리려고 해요. 컴퍼스를 얼마만큼 벌려야 하나요?","options":[{"t":"주어진 선분의 길이만큼","correct":true},{"t":"주어진 선분 길이의 2배만큼","mis":"M3-2-u3-X08"},{"t":"주어진 선분 길이의 반만큼","mis":"M3-2-u3-X08"},{"t":"아무만큼이나","mis":"M3-2-u3-X12"}],"explanation":["컴퍼스를 벌린 길이가 반지름이 돼요.","선분을 반지름으로 하려면","선분의 길이만큼 벌려요 — 침은 선분의 한 끝(원의 중심)에 꽂아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_basic#10','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',3,'ox','auto','「지름이 4 cm인 원을 그리려면 컴퍼스를 4 cm만큼 벌려야 해요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X11']::text[],true,'{"seq":10,"concept":"M3-2-u3-C6","difficulty":3,"kind":"ox","stem":"「지름이 4 cm인 원을 그리려면 컴퍼스를 4 cm만큼 벌려야 해요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"컴퍼스는 반지름만큼, 곧 2 cm만큼 벌려야 해서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"mis":"M3-2-u3-X11","explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 4 cm의 반은 2 cm예요.","2 cm만큼 벌려야 해요 — 이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"「컴퍼스로 원을 그릴 때 침을 꽂은 점은 원 위의 점이에요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"침을 꽂은 점은 원의 중심이라서","correct":true},{"t":"침도 원 위를 따라 움직여서","mis":"M3-2-u3-X12"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂고 움직이지 않아요.","원 위를 도는 것은 연필 끝이에요.","이 말은 틀렸어요(X)."]},{"stem":"「반지름이 3 cm인 원을 그리려면 컴퍼스를 3 cm만큼 벌려요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"컴퍼스를 벌린 길이가 반지름이라서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"explanation":["컴퍼스의 침과 연필 끝 사이의 거리가 반지름이에요.","반지름이 3 cm이니까","3 cm만큼 벌려요(O)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#1','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',2,'mc','auto','컬링 경기장에서는 중심이 같은 여러 가지 크기의 원을 볼 수 있어요. 컴퍼스로 이런 원들을 그릴 때 원마다 바꾸어야 하는 것은 무엇인가요?',ARRAY['M3-2-u3-X03','M3-2-u3-X12']::text[],true,'{"seq":1,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"컬링 경기장에서는 중심이 같은 여러 가지 크기의 원을 볼 수 있어요. 컴퍼스로 이런 원들을 그릴 때 원마다 바꾸어야 하는 것은 무엇인가요?","options":[{"t":"컴퍼스의 침과 연필 끝을 벌린 길이","correct":true},{"t":"컴퍼스의 침을 꽂는 곳","mis":"M3-2-u3-X03"},{"t":"연필의 색","mis":"M3-2-u3-X12"},{"t":"종이의 방향","mis":"M3-2-u3-X12"}],"explanation":["중심이 같으니 침은 같은 곳에 꽂아요.","원의 크기는 반지름이 정해요.","그래서 원마다 벌린 길이(반지름)만 바꾸어요."],"variant_rule":{"alt":[{"stem":"누름 못과 띠종이를 사용하여 여러 가지 크기의 원을 그릴 때 어려운 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"원하는 크기의 원을 그리지 못하는 경우가 생길 수 있어요","correct":true},{"t":"원의 중심이 없어도 그려져요","mis":"M3-2-u3-X12"},{"t":"누름 못을 움직여야 원이 그려져요","mis":"M3-2-u3-X23"},{"t":"반지름이 길수록 원이 작아져요","mis":"M3-2-u3-X24"}],"explanation":["띠종이의 구멍은 정해진 곳에만 있어요.","그래서 구멍 사이의 크기인 원은 그릴 수 없어요.","원하는 만큼 벌릴 수 있는 컴퍼스가 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#2','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',2,'error','auto','컴퍼스로 원을 그리는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X11','M3-2-u3-X16']::text[],true,'{"seq":2,"concept":"M3-2-u3-C6","difficulty":2,"kind":"error","stem":"컴퍼스로 원을 그리는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"가람 — 「지름이 4 cm인 원은 컴퍼스를 4 cm만큼 벌려 그려.」","correct":true,"mis_target":"M3-2-u3-X11"},{"t":"민준 — 「먼저 원의 중심이 되는 점을 정해.」","mis":"M3-2-u3-X16"},{"t":"지아 — 「컴퍼스의 침은 원의 중심에 꽂아.」","mis":"M3-2-u3-X16"},{"t":"나은 — 「반지름이 3 cm인 원은 3 cm만큼 벌려.」","mis":"M3-2-u3-X16"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 4 cm인 원은 그 반인 2 cm만큼 벌려야 해요.","가람이의 말이 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 컴퍼스로 원을 그리는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"나은 — 「지름이 2 cm인 원은 컴퍼스를 2 cm만큼 벌려 그려.」","correct":true,"mis_target":"M3-2-u3-X11"},{"t":"민준 — 「먼저 원의 중심이 되는 점을 정해.」","mis":"M3-2-u3-X16"},{"t":"지아 — 「컴퍼스의 침은 원의 중심에 꽂아.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「반지름이 2 cm인 원은 2 cm만큼 벌려.」","mis":"M3-2-u3-X16"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 2 cm인 원은 1 cm만큼 벌려야 해요.","나은이의 말이 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#3','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'mc','auto','「정보 처리」 — 주어진 모양과 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],true,'{"seq":3,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"「정보 처리」 — 주어진 모양과 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"6군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 3개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 3군데예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,45],30],[[45,75],30],[[75,75],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"같은 점을 중심으로 그린 원 3개예요. 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"1군데","correct":true},{"t":"3군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 3개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 1군데예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],45],[[60,60],30],[[60,60],15]]}],"tag":false}},{"stem":"가운데 원을 그리고 중심을 왼쪽과 오른쪽으로 옮기며 그린 원 5개예요. 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"5군데","correct":true},{"t":"6군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"10군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 5개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 5군데예요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[30,60],15],[[60,60],30],[[90,60],45],[[120,60],30],[[150,60],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#4','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'sa','auto','주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 작은 원의 중심에서 가장 큰 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 작은 원의 중심에서 가장 큰 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원 3개의 반지름은 2칸, 3칸, 4칸이고 모두 왼쪽 한 점에서 만나요.","만나는 점에서 중심까지가 반지름 — 2칸, 3칸, 4칸 떨어져 있어요.","4 − 2 = 2칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 큰 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["가장 큰 원의 반지름을 모눈으로 세면 4칸이에요.","한 원에서 지름은 반지름의 2배예요.","4 × 2 = 8칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}},{"stem":"주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가운데 크기 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가운데 크기 원의 중심을 찾아요.","원의 중심에서 원 위의 점(왼쪽 만나는 점)까지 칸을 세요.","반지름은 3칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#5','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'mc','auto','「의사소통」 — 주어진 모양(원 3개가 왼쪽 한 점에서 만나는 모양)과 똑같이 그린 방법을 바르게 설명한 것은 어느 것인가요?',ARRAY['M3-2-u3-X03','M3-2-u3-X11','M3-2-u3-X12']::text[],false,'{"seq":5,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"「의사소통」 — 주어진 모양(원 3개가 왼쪽 한 점에서 만나는 모양)과 똑같이 그린 방법을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"원 3개의 중심과 반지름을 각각 확인한 다음, 컴퍼스를 이용하여 그렸어요","correct":true},{"t":"한 점에 침을 꽂고 벌린 길이만 바꾸어 원 3개를 그렸어요","mis":"M3-2-u3-X03"},{"t":"가장 큰 원의 지름만큼 컴퍼스를 벌려 그렸어요","mis":"M3-2-u3-X11"},{"t":"원의 중심은 보지 않고 크기만 비슷하게 그렸어요","mis":"M3-2-u3-X12"}],"explanation":["주어진 모양과 똑같이 그리려면 원의 중심과 반지름을 알아야 해요.","원 3개의 중심이 서로 달라서 침을 꽂는 곳도 3군데예요.","원마다 중심과 반지름을 확인하고 컴퍼스로 그려요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#6','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'sa','auto','「조건에 알맞은 원」 — 컴퍼스를 이용하여 반지름이 3 cm인 원과 지름이 4 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"「조건에 알맞은 원」 — 컴퍼스를 이용하여 반지름이 3 cm인 원과 지름이 4 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["컴퍼스는 반지름만큼 벌려요.","반지름 3 cm인 원: 3 cm, 지름 4 cm인 원: 4의 반인 2 cm.","3 + 2 = 5(cm)예요."],"variant_rule":{"alt":[{"stem":"컴퍼스를 이용하여 반지름이 2 cm인 원과 지름이 2 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["컴퍼스는 반지름만큼 벌려요.","반지름 2 cm인 원: 2 cm, 지름 2 cm인 원: 1 cm.","2 + 1 = 3(cm)예요."]},{"stem":"컴퍼스를 이용하여 반지름이 3 cm인 원과 지름이 2 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["컴퍼스는 반지름만큼 벌려요.","반지름 3 cm인 원: 3 cm, 지름 2 cm인 원: 1 cm.","3 + 1 = 4(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#7','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'ox','auto','「수학에 퐁당」 — 「컴퍼스로 주어진 점을 모두 지나는 원을 그리려면, 먼저 주어진 점들과 같은 거리에 있는 한 점을 찾아 원의 중심으로 해야 해요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X12']::text[],false,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":3,"kind":"ox","stem":"「수학에 퐁당」 — 「컴퍼스로 주어진 점을 모두 지나는 원을 그리려면, 먼저 주어진 점들과 같은 거리에 있는 한 점을 찾아 원의 중심으로 해야 해요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"원 위의 점은 모두 원의 중심에서 같은 거리에 있어서","correct":true},{"t":"아무 점에나 침을 꽂아도 주어진 점을 지나서","mis":"M3-2-u3-X12"}],"mis":"M3-2-u3-X12","explanation":["원 위의 모든 점은 원의 중심에서 같은 거리에 있어요.","그래서 주어진 점들과 같은 거리에 있는 한 점이 원의 중심이에요.","그 점에 침을 꽂고 그 거리만큼 벌려 그려요(O)."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":15,"pts":{"ㄱ":[45,15,"n"],"ㄴ":[15,45,"w"],"ㄷ":[75,45,"e"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#8','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',4,'sa','auto','「정보 처리」 — 한 변이 모눈 8칸인 정사각형 안에 무늬가 있어요. 위쪽은 정사각형의 한가운데 점을 원의 중심으로 하여 왼쪽 변의 가운데에서 오른쪽 변의 가운데까지 그린 원의 일부이고, 아래쪽은 정사각형의 아래쪽 두 꼭짓점을 각각 원의 중심으로 하여 그린 원의 일부 2개예요. 이 무늬를 컴퍼스로 똑같이 그리려면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":4,"kind":"sa","stem":"「정보 처리」 — 한 변이 모눈 8칸인 정사각형 안에 무늬가 있어요. 위쪽은 정사각형의 한가운데 점을 원의 중심으로 하여 왼쪽 변의 가운데에서 오른쪽 변의 가운데까지 그린 원의 일부이고, 아래쪽은 정사각형의 아래쪽 두 꼭짓점을 각각 원의 중심으로 하여 그린 원의 일부 2개예요. 이 무늬를 컴퍼스로 똑같이 그리려면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["위쪽 원의 일부는 한가운데 점에서 변의 가운데까지 — 8칸의 반인 4칸이 반지름이에요.","아래쪽 원의 일부는 꼭짓점에서 변의 가운데까지 — 역시 4칸이에요.","세 번 모두 4칸만큼 벌려요."],"variant_rule":{"alt":[{"stem":"「정보 처리」 — 한 변이 모눈 8칸인 정사각형 안에 무늬가 있어요. 위쪽은 정사각형의 한가운데 점을 원의 중심으로 하여 왼쪽 변의 가운데에서 오른쪽 변의 가운데까지 그린 원의 일부이고, 아래쪽은 정사각형의 아래쪽 두 꼭짓점을 각각 원의 중심으로 하여 그린 원의 일부 2개예요. 이 무늬를 컴퍼스로 똑같이 그리려면 컴퍼스의 침을 모두 몇 군데에 꽂아야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원의 중심은 정사각형의 한가운데 점, 아래쪽 두 꼭짓점이에요.","모두 3군데예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#9','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',4,'sa','auto','「수학에 퐁당」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ을 모두 지나는 원을 컴퍼스로 그리려고 해요. 세 점과 같은 거리에 있는 점을 원의 중심으로 하면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C6","difficulty":4,"kind":"sa","stem":"「수학에 퐁당」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ을 모두 지나는 원을 컴퍼스로 그리려고 해요. 세 점과 같은 거리에 있는 점을 원의 중심으로 하면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["세 점과 같은 거리에 있는 점은 점 ㄱ에서 아래로 2칸인 점이에요.","그 점에서 ㄱ, ㄴ, ㄷ까지 모두 2칸이에요.","그 점에 침을 꽂고 2칸만큼 벌려요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":15,"pts":{"ㄱ":[45,15,"n"],"ㄴ":[15,45,"w"],"ㄷ":[75,45,"e"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학에 퐁당」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ을 모두 지나는 원을 그렸어요. 이 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["원의 중심은 세 점과 같은 거리에 있는 점이에요 — 반지름 2칸.","점 ㄴ과 점 ㄷ을 이은 선분은 원의 중심을 지나요.","지름은 2 × 2 = 4칸이에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":15,"pts":{"ㄱ":[45,15,"n"],"ㄴ":[15,45,"w"],"ㄷ":[75,45,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L05_challenge#10','math',3,2,'u3','L05','tb_g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',4,'essay','teacher','컴퍼스를 이용하여 지름이 4 cm인 원을 그리는 방법을 차례대로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C6","difficulty":4,"kind":"essay","stem":"컴퍼스를 이용하여 지름이 4 cm인 원을 그리는 방법을 차례대로 써 보세요.","answer_guide":{"answer":"예: ① 원의 중심이 되는 점 ㅇ을 정한다. ② 반지름은 지름의 반이므로 2 cm이다. 자를 이용하여 컴퍼스의 침과 연필의 끝부분을 2 cm만큼 벌린다. ③ 컴퍼스의 침을 점 ㅇ에 꽂고 컴퍼스를 돌려서 원을 그린다.","scoring_points":["원의 중심을 먼저 정했는가","지름의 반인 2 cm만큼 벌린다고 썼는가","침을 원의 중심에 꽂고 돌려 그린다고 썼는가"]},"explanation":["① 원의 중심 정하기.","② 반지름(지름의 반 = 2 cm)만큼 벌리기.","③ 침을 원의 중심에 꽂고 돌리기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#1','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'mc','auto','모눈 위에 다양한 크기의 원을 나열했어요. 원의 반지름은 어떻게 바뀌나요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":1,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"모눈 위에 다양한 크기의 원을 나열했어요. 원의 반지름은 어떻게 바뀌나요?","options":[{"t":"모눈 1칸, 2칸이 되풀이돼요","correct":true},{"t":"모눈 1칸씩 커져요","mis":"M3-2-u3-X14"},{"t":"모두 모눈 1칸이에요","mis":"M3-2-u3-X14"},{"t":"모눈 2칸, 1칸, 1칸이 되풀이돼요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 세어요.","반지름: 1칸, 2칸, 1칸, 2칸.","반지름이 1칸, 2칸으로 되풀이돼요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학과 교구 및 공학 도구」 — 원의 반지름은 어떻게 바뀌나요?","options":[{"t":"반지름이 모두 모눈 2칸으로 같아요","correct":true},{"t":"모눈 1칸씩 커져요","mis":"M3-2-u3-X14"},{"t":"모눈 1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"모눈 2칸씩 작아져요","mis":"M3-2-u3-X14"}],"explanation":["원마다 반지름을 모눈 칸으로 세어요.","모두 2칸이에요.","반지름은 변하지 않고 원의 중심만 옮겨 가요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[45,75],30],[[75,45],30],[[105,75],30],[[135,45],30]],"pts":{"①":[45,75,"n"],"②":[75,45,"n"],"③":[105,75,"n"],"④":[135,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#2','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'mc','auto','원의 중심을 표시하고 보니 원의 중심은 어떻게 옮겨 가나요?',ARRAY['M3-2-u3-X13']::text[],true,'{"seq":2,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"원의 중심을 표시하고 보니 원의 중심은 어떻게 옮겨 가나요?","options":[{"t":"오른쪽으로 2칸씩","correct":true},{"t":"오른쪽으로 1칸씩","mis":"M3-2-u3-X13"},{"t":"오른쪽으로 3칸씩","mis":"M3-2-u3-X13"},{"t":"왼쪽으로 2칸씩","mis":"M3-2-u3-X13"}],"explanation":["원의 중심 ①, ②, ③, ④를 차례로 따라가요.","이웃한 중심 사이를 세면 모두 2칸이에요.","원의 중심은 오른쪽으로 2칸씩 옮겨 가요 — 원이 맞닿지 않고 겹쳐 있어요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학과 교구 및 공학 도구」 — 원의 중심은 어떻게 옮겨 가나요?","options":[{"t":"오른쪽으로 2칸·위쪽으로 2칸, 오른쪽으로 2칸·아래쪽으로 2칸이 되풀이돼요","correct":true},{"t":"오른쪽으로만 2칸씩","mis":"M3-2-u3-X13"},{"t":"위쪽으로만 2칸씩","mis":"M3-2-u3-X13"},{"t":"오른쪽으로 4칸씩","mis":"M3-2-u3-X13"}],"explanation":["원의 중심 ①에서 ②로: 오른쪽 2칸, 위쪽 2칸.","②에서 ③으로: 오른쪽 2칸, 아래쪽 2칸.","이것이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[45,75],30],[[75,45],30],[[105,75],30],[[135,45],30]],"pts":{"①":[45,75,"n"],"②":[75,45,"n"],"③":[105,75,"n"],"④":[135,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#3','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'sa','auto','이 규칙에 맞게 원을 2개 더 그리려고 해요. 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C7","difficulty":1,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그리려고 해요. 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름을 차례로 쓰면 1칸, 2칸, 1칸, 2칸이에요.","1칸, 2칸이 되풀이돼요.","다섯째 원의 반지름은 1칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙에 맞게 원을 2개 더 그리려고 해요. 여섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반지름: 1칸, 2칸, 1칸, 2칸, 1칸, …","1칸, 2칸이 되풀이돼요.","여섯째 원의 반지름은 2칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#4','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'mc','auto','알지오매스 키즈에서 원 그리기 도구를 선택한 다음, 원의 중심으로 사용할 한 점을 선택했어요. 이어서 무엇을 선택해야 원이 그려지나요?',ARRAY['M3-2-u3-X12','M3-2-u3-X11','M3-2-u3-X02']::text[],true,'{"seq":4,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"알지오매스 키즈에서 원 그리기 도구를 선택한 다음, 원의 중심으로 사용할 한 점을 선택했어요. 이어서 무엇을 선택해야 원이 그려지나요?","options":[{"t":"원 위의 한 점","correct":true},{"t":"원의 중심 한 번 더","mis":"M3-2-u3-X12"},{"t":"지름의 양 끝 두 점","mis":"M3-2-u3-X11"},{"t":"원 밖의 아무 점","mis":"M3-2-u3-X02"}],"explanation":["원은 원의 중심과 반지름이 정해지면 그려져요.","원의 중심을 고른 다음 원 위의 한 점을 고르면 그 사이가 반지름이 돼요.","그러면 원이 그려져요."],"variant_rule":{"alt":[{"stem":"알지오매스 키즈를 이용하여 원을 그릴 때의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"원을 쉽게 그리고 지울 수 있어요","correct":true},{"t":"원의 중심을 정하지 않아도 돼요","mis":"M3-2-u3-X12"},{"t":"반지름을 정하지 않아도 돼요","mis":"M3-2-u3-X12"},{"t":"찌그러진 모양도 원이 돼요","mis":"M3-2-u3-X01"}],"explanation":["친구들은 「원을 쉽게 그리고 지울 수 있어.」, 「원을 정확하게 그릴 수 있어.」라고 말했어요.","화면에서도 원의 중심과 반지름은 꼭 정해야 해요.","그래서 답은 「원을 쉽게 그리고 지울 수 있어요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#5','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'mc','auto','「규칙에 맞게 원을 2개 더」 — 다섯째 원을 컴퍼스로 그리려고 해요. 어떻게 그려야 하나요?',ARRAY['M3-2-u3-X14','M3-2-u3-X13']::text[],true,'{"seq":5,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「규칙에 맞게 원을 2개 더」 — 다섯째 원을 컴퍼스로 그리려고 해요. 어떻게 그려야 하나요?","options":[{"t":"넷째 원의 중심에서 오른쪽으로 2칸 옮긴 곳에 원의 중심을 찍고, 컴퍼스를 1칸만큼 벌려 그려요","correct":true},{"t":"넷째 원의 중심에서 오른쪽으로 2칸 옮긴 곳에 원의 중심을 찍고, 컴퍼스를 2칸만큼 벌려 그려요","mis":"M3-2-u3-X14"},{"t":"넷째 원의 중심에서 오른쪽으로 3칸 옮긴 곳에 원의 중심을 찍고, 컴퍼스를 1칸만큼 벌려 그려요","mis":"M3-2-u3-X13"},{"t":"넷째 원과 같은 중심에 침을 꽂고, 컴퍼스를 1칸만큼 벌려 그려요","mis":"M3-2-u3-X13"}],"explanation":["원의 중심은 오른쪽으로 2칸씩 옮겨 가요.","반지름은 1칸, 2칸이 되풀이돼요 — 넷째가 2칸이니 다섯째는 1칸이에요.","중심을 오른쪽으로 2칸 옮겨 찍고 1칸만큼 벌려 그려요(여섯째는 다시 2칸 옮겨 2칸)."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「규칙에 맞게 원을 2개 더」 — 여섯째 원을 컴퍼스로 그리려고 해요. 어떻게 그려야 하나요?","options":[{"t":"다섯째 원의 중심에서 오른쪽으로 2칸 옮긴 곳에 원의 중심을 찍고, 컴퍼스를 2칸만큼 벌려 그려요","correct":true},{"t":"다섯째 원의 중심에서 오른쪽으로 2칸 옮긴 곳에 원의 중심을 찍고, 컴퍼스를 1칸만큼 벌려 그려요","mis":"M3-2-u3-X14"},{"t":"다섯째 원의 중심에서 오른쪽으로 3칸 옮긴 곳에 원의 중심을 찍고, 컴퍼스를 2칸만큼 벌려 그려요","mis":"M3-2-u3-X13"},{"t":"다섯째 원과 같은 중심에 침을 꽂고, 컴퍼스를 2칸만큼 벌려 그려요","mis":"M3-2-u3-X13"}],"explanation":["원의 중심은 오른쪽으로 2칸씩 옮겨 가요.","다섯째가 1칸이니 여섯째는 2칸이에요.","중심을 오른쪽으로 2칸 옮겨 찍고 2칸만큼 벌려 그려요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#6','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'mc','auto','「어떻게 그렸는지」 — 이 모양을 그린 방법을 바르게 설명한 것은 어느 것인가요?',ARRAY['M3-2-u3-X13','M3-2-u3-X14']::text[],true,'{"seq":6,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「어떻게 그렸는지」 — 이 모양을 그린 방법을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"가운데에 반지름이 모눈 3칸인 원을 그리고, 원의 중심을 왼쪽과 오른쪽으로 2칸씩 옮기며 반지름 2칸, 1칸인 원을 그렸어요","correct":true},{"t":"같은 점을 중심으로 반지름 3칸, 2칸, 1칸인 원을 그렸어요","mis":"M3-2-u3-X13"},{"t":"왼쪽부터 반지름을 1칸씩 늘리며 그렸어요","mis":"M3-2-u3-X14"},{"t":"원의 중심을 1칸씩 옮기며 같은 크기의 원을 그렸어요","mis":"M3-2-u3-X13"}],"explanation":["가운데 원의 반지름은 3칸이에요.","중심이 왼쪽·오른쪽으로 2칸씩 옮겨 가며 반지름이 2칸, 1칸으로 줄어요.","중심과 반지름이 함께 바뀌는 규칙이에요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[30,60],15],[[60,60],30],[[90,60],45],[[120,60],30],[[150,60],15]],"pts":{"①":[30,60,"n"],"②":[60,60,"n"],"③":[90,60,"n"],"④":[120,60,"n"],"⑤":[150,60,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 「어떻게 그렸는지」 — 이 모양을 그린 방법을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"같은 점을 원의 중심으로 하여 반지름이 모눈 3칸, 2칸, 1칸인 원을 그렸어요","correct":true},{"t":"원의 중심을 왼쪽과 오른쪽으로 2칸씩 옮기며 그렸어요","mis":"M3-2-u3-X13"},{"t":"반지름은 그대로 두고 원의 중심만 옮겼어요","mis":"M3-2-u3-X14"},{"t":"반지름을 1칸씩 늘리며 원이 맞닿게 그렸어요","mis":"M3-2-u3-X13"}],"explanation":["원 3개의 중심이 모두 같은 점이에요.","반지름만 3칸, 2칸, 1칸으로 달라요.","중심을 옮기지 않고 벌린 길이만 바꾸어 그렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],45],[[60,60],30],[[60,60],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#7','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'sa','auto','「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림이에요. 점 ㅁ을 원의 중심으로 하는 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림이에요. 점 ㅁ을 원의 중심으로 하는 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㅁ은 셋째 원의 중심이에요.","점 ㅁ에서 원 위의 점 ㄹ까지 칸을 세요.","반지름은 3칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림이에요. 점 ㄷ을 원의 중심으로 하는 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["점 ㄷ은 둘째 원의 중심이에요.","점 ㄷ에서 원 위의 점 ㄴ까지 칸을 세요.","반지름은 2칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}},{"stem":"「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림이에요. 점 ㅅ을 원의 중심으로 하는 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["점 ㅅ은 넷째 원의 중심이에요.","점 ㅅ에서 원 위의 점 ㅂ까지 칸을 세요.","반지름은 4칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#8','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'mc','auto','「수학과 교구 및 공학 도구」 — 이 규칙에 맞게 원을 2개 더 그리려고 해요. 다섯째 원의 중심은 넷째 원의 중심에서 어느 쪽으로 옮기면 되나요?',ARRAY['M3-2-u3-X13']::text[],false,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「수학과 교구 및 공학 도구」 — 이 규칙에 맞게 원을 2개 더 그리려고 해요. 다섯째 원의 중심은 넷째 원의 중심에서 어느 쪽으로 옮기면 되나요?","options":[{"t":"오른쪽으로 2칸, 아래쪽으로 2칸","correct":true},{"t":"오른쪽으로 2칸, 위쪽으로 2칸","mis":"M3-2-u3-X13"},{"t":"오른쪽으로 4칸","mis":"M3-2-u3-X13"},{"t":"아래쪽으로 2칸","mis":"M3-2-u3-X13"}],"explanation":["원의 중심은 오른쪽 2칸·위쪽 2칸, 오른쪽 2칸·아래쪽 2칸이 되풀이돼요.","넷째 원은 위쪽으로 옮겨 그린 원이에요.","다섯째 원은 오른쪽으로 2칸, 아래쪽으로 2칸 옮겨 반지름 2칸으로 그려요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[45,75],30],[[75,45],30],[[105,75],30],[[135,45],30]],"pts":{"①":[45,75,"n"],"②":[75,45,"n"],"③":[105,75,"n"],"④":[135,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#9','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'sa','auto','가운데 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"가운데 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가운데 원의 반지름을 모눈으로 세면 3칸이에요.","한 원에서 지름은 반지름의 2배예요.","3 × 2 = 6칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[30,60],15],[[60,60],30],[[90,60],45],[[120,60],30],[[150,60],15]],"pts":{"①":[30,60,"n"],"②":[60,60,"n"],"③":[90,60,"n"],"④":[120,60,"n"],"⑤":[150,60,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"둘째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["둘째 원의 반지름을 모눈으로 세면 2칸이에요.","한 원에서 지름은 반지름의 2배예요.","2 × 2 = 4칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}},{"stem":"점 ㅅ을 원의 중심으로 하는 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㅅ이 중심인 원의 반지름은 4칸이에요.","한 원에서 지름은 반지름의 2배예요.","4 × 2 = 8칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_basic#10','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',3,'ox','auto','「수학과 교구 및 공학 도구」 — 「이 무늬에서 원의 반지름은 모두 같고, 원의 중심만 옮겨 가요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":10,"concept":"M3-2-u3-C7","difficulty":3,"kind":"ox","stem":"「수학과 교구 및 공학 도구」 — 「이 무늬에서 원의 반지름은 모두 같고, 원의 중심만 옮겨 가요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름이 모두 모눈 2칸이고 중심만 오른쪽 위·오른쪽 아래로 옮겨 가서","correct":true},{"t":"원의 크기가 점점 커져서","mis":"M3-2-u3-X14"}],"mis":"M3-2-u3-X14","explanation":["원마다 반지름을 세면 모두 2칸이에요.","원의 중심은 오른쪽으로 2칸씩 가며 위·아래로 번갈아 옮겨 가요.","맞는 말이에요(O)."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[45,75],30],[[75,45],30],[[105,75],30],[[135,45],30]],"pts":{"①":[45,75,"n"],"②":[75,45,"n"],"③":[105,75,"n"],"④":[135,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"「이 무늬에서 원들은 서로 맞닿게 이어져 있어요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"원의 중심이 2칸씩만 옮겨 가서 원들이 서로 겹쳐 있어서","correct":true},{"t":"원의 중심이 반지름의 합만큼 옮겨 가서","mis":"M3-2-u3-X13"}],"explanation":["반지름 1칸·2칸인 원이 맞닿으려면 중심 사이가 3칸이어야 해요.","이 무늬는 중심이 2칸씩 옮겨 가요.","그래서 원들이 겹쳐 있어요 — 이 말은 틀렸어요(X)."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#1','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',2,'mc','auto','「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림에서 원의 반지름은 어떻게 바뀌나요?',ARRAY['M3-2-u3-X14']::text[],false,'{"seq":1,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림에서 원의 반지름은 어떻게 바뀌나요?","options":[{"t":"모눈 1칸씩 커져요","correct":true},{"t":"모눈 1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"모두 모눈 2칸이에요","mis":"M3-2-u3-X14"},{"t":"모눈 2칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["점 ㄱ, ㄷ, ㅁ, ㅅ이 원의 중심이에요.","반지름: 1칸, 2칸, 3칸, 4칸.","반지름이 1칸씩 커지고, 원은 서로 맞닿아 있어요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#2','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',2,'sa','auto','이 규칙에 맞게 원을 계속 그리면 일곱째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"이 규칙에 맞게 원을 계속 그리면 일곱째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름: 1칸, 2칸이 되풀이돼요.","1, 2, 1, 2, 1, 2, 1.","일곱째 원의 반지름은 1칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙에 맞게 원을 계속 그리면 여덟째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반지름: 1칸, 2칸이 되풀이돼요.","짝수째 원은 2칸이에요.","여덟째 원의 반지름은 2칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#3','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'sa','auto','이 규칙에 맞게 원을 2개 더 그렸어요. 첫째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그렸어요. 첫째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["원의 중심은 오른쪽으로 2칸씩 옮겨 가요.","첫째에서 다섯째까지 4번 옮겨요.","2 × 4 = 8칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙에 맞게 원을 2개 더 그렸어요. 첫째 원의 중심에서 여섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["원의 중심은 오른쪽으로 2칸씩 옮겨 가요.","첫째에서 여섯째까지 5번 옮겨요.","2 × 5 = 10칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#4','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'sa','auto','원이 맞닿게 이어진 그림이에요. 점 ㄱ에서 점 ㅅ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"원이 맞닿게 이어진 그림이에요. 점 ㄱ에서 점 ㅅ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["점 ㄱ, ㄷ, ㅁ, ㅅ은 원의 중심, 점 ㄴ, ㄹ, ㅂ은 원이 맞닿은 점이에요.","1(첫째 원의 반지름) + 2 + 2 + 3 + 3 + 4 = 15.","점 ㄱ에서 점 ㅅ까지 15칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"원이 맞닿게 이어진 그림이에요. 점 ㄷ에서 점 ㅁ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㄷ은 둘째 원, 점 ㅁ은 셋째 원의 중심이에요.","두 원이 맞닿아 있어 반지름 2칸 + 반지름 3칸이에요.","2 + 3 = 5칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}},{"stem":"원이 맞닿게 이어진 그림이에요. 점 ㄴ에서 점 ㅂ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["점 ㄴ에서 점 ㄹ까지는 둘째 원의 지름, 점 ㄹ에서 점 ㅂ까지는 셋째 원의 지름이에요.","2 × 2 = 4칸, 3 × 2 = 6칸.","4 + 6 = 10칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#5','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'mc','auto','「수학과 교구 및 공학 도구」 — 이 원 무늬를 만든 규칙을 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u3-X14','M3-2-u3-X13']::text[],false,'{"seq":5,"concept":"M3-2-u3-C7","difficulty":3,"kind":"mc","stem":"「수학과 교구 및 공학 도구」 — 이 원 무늬를 만든 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"반지름은 그대로 두고, 원의 중심을 오른쪽으로 2칸·위쪽으로 2칸, 오른쪽으로 2칸·아래쪽으로 2칸씩 번갈아 옮겼어요","correct":true},{"t":"반지름을 1칸씩 늘리고, 원의 중심을 오른쪽으로 옮겼어요","mis":"M3-2-u3-X14"},{"t":"반지름은 그대로 두고, 원의 중심을 오른쪽으로만 옮겼어요","mis":"M3-2-u3-X13"},{"t":"원의 중심은 그대로 두고 반지름만 바꾸었어요","mis":"M3-2-u3-X13"}],"explanation":["반지름이 어떻게 바뀌는지 먼저 봐요 — 모두 2칸이에요.","다음에 원의 중심이 어디로 옮겨 가는지 봐요.","오른쪽 위, 오른쪽 아래로 번갈아 2칸씩 옮겨 가요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[45,75],30],[[75,45],30],[[105,75],30],[[135,45],30]],"pts":{"①":[45,75,"n"],"②":[75,45,"n"],"③":[105,75,"n"],"④":[135,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#6','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'sa','auto','같은 점을 원의 중심으로 하여 반지름이 모눈 3칸, 2칸, 1칸인 원을 그렸어요. 가장 큰 원의 지름은 가장 작은 원의 지름보다 모눈 몇 칸 더 긴가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"같은 점을 원의 중심으로 하여 반지름이 모눈 3칸, 2칸, 1칸인 원을 그렸어요. 가장 큰 원의 지름은 가장 작은 원의 지름보다 모눈 몇 칸 더 긴가요? 숫자로 쓰세요.","answer":["4"],"explanation":["지름은 반지름의 2배예요.","가장 큰 원: 3 × 2 = 6칸, 가장 작은 원: 1 × 2 = 2칸.","6 − 2 = 4칸이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],45],[[60,60],30],[[60,60],15]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가운데에 반지름이 모눈 3칸인 원을 그리고, 원의 중심을 왼쪽과 오른쪽으로 2칸씩 옮기며 반지름 2칸, 1칸인 원을 그렸어요. 모양의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가장 왼쪽 원은 중심이 가운데에서 4칸 왼쪽, 반지름 1칸 — 왼쪽 끝은 가운데에서 5칸.","오른쪽도 똑같이 5칸이에요.","5 + 5 = 10칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[30,60],15],[[60,60],30],[[90,60],45],[[120,60],30],[[150,60],15]],"pts":{"①":[30,60,"n"],"②":[60,60,"n"],"③":[90,60,"n"],"④":[120,60,"n"],"⑤":[150,60,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#7','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'error','auto','이 원 무늬의 규칙을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u3-X14','M3-2-u3-X16']::text[],false,'{"seq":7,"concept":"M3-2-u3-C7","difficulty":3,"kind":"error","stem":"이 원 무늬의 규칙을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「다섯째 원의 반지름은 2칸이야.」","correct":true,"mis_target":"M3-2-u3-X14"},{"t":"서준 — 「반지름이 1칸, 2칸으로 되풀이돼.」","mis":"M3-2-u3-X16"},{"t":"지유 — 「원의 중심은 오른쪽으로 2칸씩 옮겨 가.」","mis":"M3-2-u3-X16"},{"t":"건우 — 「원들이 서로 겹쳐 있어.」","mis":"M3-2-u3-X16"}],"explanation":["반지름은 1칸, 2칸이 되풀이돼요.","다섯째 원은 홀수째라 반지름이 1칸이에요.","은비의 말이 잘못이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#8','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',4,'sa','auto','이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 반지름이 모눈 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":4,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 반지름이 모눈 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반지름: 1칸, 2칸이 되풀이돼요.","6개를 차례로 쓰면 1, 2, 1, 2, 1, 2.","반지름 2칸인 원은 3개예요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#9','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',4,'sa','auto','이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C7","difficulty":4,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["첫째 원의 왼쪽 끝은 첫째 중심에서 1칸 왼쪽이에요.","여섯째 원의 중심은 첫째 중심에서 2 × 5 = 10칸 오른쪽, 반지름 2칸이에요.","1 + 10 + 2 = 13칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"원이 맞닿게 이어진 그림이에요. 그림의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["가로에는 원마다 지름이 하나씩 놓여요.","지름: 2칸, 4칸, 6칸, 8칸.","2 + 4 + 6 + 8 = 20칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}},{"stem":"「수학과 교구 및 공학 도구」 — 이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["반지름은 모두 2칸, 원의 중심은 오른쪽으로 2칸씩 옮겨 가요.","첫째 중심에서 여섯째 중심까지 2 × 5 = 10칸.","2 + 10 + 2 = 14칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[45,75],30],[[75,45],30],[[105,75],30],[[135,45],30]],"pts":{"①":[45,75,"n"],"②":[75,45,"n"],"③":[105,75,"n"],"④":[135,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_L06_challenge#10','math',3,2,'u3','L06','tb_g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',4,'essay','teacher','「나만의 규칙」 — 컴퍼스로 다양한 크기의 원을 그려 나만의 무늬를 만들려고 해요. 원의 중심을 옮기는 규칙과 반지름의 규칙을 정해 쓰고, 어떻게 그렸는지 과정을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C7","difficulty":4,"kind":"essay","stem":"「나만의 규칙」 — 컴퍼스로 다양한 크기의 원을 그려 나만의 무늬를 만들려고 해요. 원의 중심을 옮기는 규칙과 반지름의 규칙을 정해 쓰고, 어떻게 그렸는지 과정을 설명해 보세요.","answer_guide":{"answer":"예: 가운데에 반지름이 모눈 3칸인 원을 그리고, 원의 중심을 왼쪽과 오른쪽으로 각각 2칸씩 옮기며 반지름이 모눈 2칸, 1칸인 원을 그린다. 원을 그릴 때마다 먼저 원의 중심을 찍고 컴퍼스를 반지름만큼 벌려 돌린다.","scoring_points":["원의 중심을 옮기는 규칙을 썼는가","반지름이 바뀌는(또는 그대로인) 규칙을 썼는가","중심을 찍고 반지름만큼 벌려 그리는 과정을 설명했는가"]},"explanation":["원의 중심을 어느 쪽으로 몇 칸 옮길지 정해요.","반지름이 어떻게 바뀔지 정해요.","그릴 때마다 중심 → 반지름만큼 벌리기 → 돌리기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#1','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C4',1,'mc','auto','「빈칸을 채우세요」 — 한 원에서 지름은 반지름의 몇 배인가요?',ARRAY['M3-2-u3-X08','M3-2-u3-X09']::text[],false,'{"seq":1,"concept":"M3-2-u3-C4","difficulty":1,"kind":"mc","stem":"「빈칸을 채우세요」 — 한 원에서 지름은 반지름의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"반","mis":"M3-2-u3-X08"},{"t":"1배(같아요)","mis":"M3-2-u3-X09"},{"t":"3배","mis":"M3-2-u3-X09"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","반지름이 1 cm면 지름은 2 cm예요.","한 원에서 지름은 반지름의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#2','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',1,'mc','auto','「스스로 마무리하기」 — 그림에서 원의 지름은 어느 선분인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X07']::text[],false,'{"seq":2,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 그림에서 원의 지름은 어느 선분인가요?","options":[{"t":"선분 ㄹㅂ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅅ","mis":"M3-2-u3-X06"},{"t":"선분 ㅇㄷ","mis":"M3-2-u3-X07"}],"explanation":["지름은 원 위의 두 점을 이은 선분이 원의 중심을 지날 때의 선분이에요.","선분 ㄱㄴ, ㅁㅅ은 원의 중심을 지나지 않고, 선분 ㅇㄷ은 반지름이에요.","지름은 선분 ㄹㅂ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㄴ":[85.1,25.3,"n"],"ㄷ":[64.9,100.7,"s"],"ㄹ":[94.5,96.8,"se"],"ㅁ":[104.9,37.9,"ne"],"ㅂ":[55.5,29.2,"nw"],"ㅅ":[108.8,82.5,"se"],"ㅇ":[75,63.0,"ne"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅂ"],["ㅁ","ㅅ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#3','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',1,'sa','auto','「스스로 마무리하기」 — 원에 지름을 한 개 긋고 재어 보니 지름 하나가 4 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 — 원에 지름을 한 개 긋고 재어 보니 지름 하나가 4 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 4 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#4','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C4',1,'mc','auto','「스스로 마무리하기」 — 점 ㅇ은 원의 중심이에요. 원 위의 한 점에서 그은 8 cm, 12 cm, 10 cm 선분 가운데 12 cm 선분만 원의 중심을 지나요. 이 원의 반지름은 몇 cm인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X20']::text[],false,'{"seq":4,"concept":"M3-2-u3-C4","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 점 ㅇ은 원의 중심이에요. 원 위의 한 점에서 그은 8 cm, 12 cm, 10 cm 선분 가운데 12 cm 선분만 원의 중심을 지나요. 이 원의 반지름은 몇 cm인가요?","options":[{"t":"6 cm","correct":true},{"t":"12 cm","mis":"M3-2-u3-X07"},{"t":"4 cm","mis":"M3-2-u3-X20"},{"t":"5 cm","mis":"M3-2-u3-X20"}],"explanation":["원의 중심을 지나는 12 cm 선분이 지름이에요.","반지름은 지름의 반이에요.","12의 반 — 반지름은 6 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[112.7,73.1,"e"],"ㄴ":[64.9,25.3,"n"],"ㄷ":[37.3,52.9,"w"],"ㄹ":[49.9,92.9,"sw"],"ㅇ":[75,63.0,"n"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"]],"lab":[[[110.5,27.5],"8 cm"],[[55.3,68.6],"12 cm"],[[90.1,110.9],"10 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#5','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',1,'mc','auto','「스스로 마무리하기」 — 원에 대해 바르게 설명한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X21']::text[],false,'{"seq":5,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 원에 대해 바르게 설명한 사람은 누구인가요?","options":[{"t":"은비 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 원의 지름이야.」","correct":true},{"t":"서준 — 「한 원에 지름은 한 개 그을 수 있어.」","mis":"M3-2-u3-X04"},{"t":"지유 — 「원의 중심은 원을 똑같이 둘로 나눠.」","mis":"M3-2-u3-X21"},{"t":"건우 — 「한 원에 반지름은 2개 그을 수 있어.」","mis":"M3-2-u3-X04"}],"explanation":["한 원에 지름과 반지름은 무수히 많아요.","원을 똑같이 둘로 나누는 것은 지름이에요.","바르게 설명한 사람은 은비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#6','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',1,'mc','auto','「추론」 — 크기가 큰 원부터 차례대로 기호를 쓴 것은 어느 것인가요? (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)',ARRAY['M3-2-u3-X10','M3-2-u3-X16']::text[],false,'{"seq":6,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"「추론」 — 크기가 큰 원부터 차례대로 기호를 쓴 것은 어느 것인가요? (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)","options":[{"t":"㉢, ㉡, ㉠, ㉣","correct":true},{"t":"㉠, ㉢, ㉡, ㉣","mis":"M3-2-u3-X10"},{"t":"㉣, ㉠, ㉡, ㉢","mis":"M3-2-u3-X16"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M3-2-u3-X10"}],"explanation":["크기가 큰 원은 지름(반지름)이 긴 원이에요 — 모두 지름으로 바꾸어요.","㉠ 6 cm, ㉡ 8 cm, ㉢ 12 cm, ㉣ 4 cm.","큰 것부터 ㉢, ㉡, ㉠, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#7','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',1,'ox','auto','「서술형」 — 지름이 2 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 자의 눈금 0과 2에 맞추어 벌렸어요. 이렇게 벌린 것이 옳은가요?',ARRAY['M3-2-u3-X11']::text[],false,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"ox","stem":"「서술형」 — 지름이 2 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 자의 눈금 0과 2에 맞추어 벌렸어요. 이렇게 벌린 것이 옳은가요?","answer":"X","reason_options":[{"t":"지름이 2 cm인 원은 1 cm만큼 벌려야 하는데 2 cm만큼 벌려서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"mis":"M3-2-u3-X11","explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 2 cm인 원의 반지름은 1 cm예요.","2 cm만큼 벌린 그림은 옳지 않아요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#8','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',1,'mc','auto','「스스로 마무리하기」 — 주어진 모양과 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],false,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 주어진 모양과 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"6군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 3개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 3군데예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,45],30],[[45,75],30],[[75,75],30]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#9','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C4',2,'sa','auto','「이 단원 학습을 마치고」 — 만화에 반지름이 약 20 m인 피자가 나와요. 이 피자의 지름은 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"「이 단원 학습을 마치고」 — 만화에 반지름이 약 20 m인 피자가 나와요. 이 피자의 지름은 약 몇 m인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["한 원에서 지름은 반지름의 2배예요.","20 × 2 = 40이에요.","지름은 약 40 m예요 — 우리가 먹은 피자보다 훨씬 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#10','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C8',2,'sa','auto','원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 맨 위에서 맨 아래까지 두 원의 중심을 지나게 그은 선분의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C8","difficulty":2,"kind":"sa","stem":"원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 맨 위에서 맨 아래까지 두 원의 중심을 지나게 그은 선분의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["선분 위에 두 원의 지름이 이어져 있어요.","2 × 2 = 4(cm), 5 × 2 = 10(cm).","4 + 10 = 14(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":141.0,"circle":[[[52.5,33.0],15.0],[[52.5,85.5],37.5]],"pts":{"ㄱ":[52.5,33.0,"e"],"ㄴ":[52.5,85.5,"e"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#11','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C4',2,'mc','auto','「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 4 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],false,'{"seq":11,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 4 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 8 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 16 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 4 cm인 원의 지름은 4 × 2 = 8(cm)예요.","그래서 「지름이 8 cm인 원」 카드와 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#12','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',2,'sa','auto','「조건에 알맞은 원」 — 지름이 4 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"「조건에 알맞은 원」 — 지름이 4 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 4 cm의 반은 2 cm예요.","2 cm만큼 벌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#13','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C1',2,'mc','auto','원 위의 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],false,'{"seq":13,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄴ만 선 위에 있어요. 점 ㄱ은 원 안, 점 ㄷ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄴ":[93.8,30.5,"ne"],"ㄱ":[59.1,68.8,"nw"],"ㄷ":[120.5,89.2,"se"]},"circle":[[[75,63.0],37.5]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#14','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C2',2,'mc','auto','누름 못과 띠종이로 원을 그렸어요. 띠종이의 구멍 ㄴ에 누름 못을 꽂고, 구멍 ㄷ에 연필을 꽂아 한 바퀴 돌렸어요. 원의 중심은 어느 것인가요?',ARRAY['M3-2-u3-X03']::text[],false,'{"seq":14,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"누름 못과 띠종이로 원을 그렸어요. 띠종이의 구멍 ㄴ에 누름 못을 꽂고, 구멍 ㄷ에 연필을 꽂아 한 바퀴 돌렸어요. 원의 중심은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X03"},{"t":"점 ㄷ","mis":"M3-2-u3-X03"},{"t":"점 ㄹ","mis":"M3-2-u3-X03"}],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","점 ㄷ·ㄹ은 원 위의 점, 점 ㄱ은 원 안의 점이에요.","원의 중심은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[107.6,47.8,"ne"],"ㅁ":[123.9,40.2,"ne"],"ㄱ":[55.9,57.9,"nw"],"ㄹ":[102.6,86.1,"se"],"ㄴ":[75,63.0,"sw"]},"circle":[[[75,63.0],36.0]],"seg":[["ㄴ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#15','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C7',2,'sa','auto','이 규칙에 맞게 원을 2개 더 그리려고 해요. 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그리려고 해요. 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름: 1칸, 2칸, 1칸, 2칸.","1칸, 2칸이 되풀이돼요.","다섯째 원의 반지름은 1칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#16','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',2,'mc','auto','선분 ㄱㄴ, 선분 ㄱㄷ, 선분 ㄱㄹ, 선분 ㄱㅁ 가운데 길이가 가장 긴 선분은 어느 것인가요?',ARRAY['M3-2-u3-X17']::text[],false,'{"seq":16,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"선분 ㄱㄴ, 선분 ㄱㄷ, 선분 ㄱㄹ, 선분 ㄱㅁ 가운데 길이가 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","그중 원의 중심 ㅇ을 지나는 선분 ㄱㄹ이 지름이에요.","원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,49.7,"w"],"ㄴ":[68.2,24.6,"n"],"ㄷ":[94.5,29.2,"ne"],"ㄹ":[111.6,76.3,"e"],"ㅁ":[68.2,101.4,"s"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#17','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C2',3,'error','auto','원의 중심과 반지름에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X16']::text[],false,'{"seq":17,"concept":"M3-2-u3-C2","difficulty":3,"kind":"error","stem":"원의 중심과 반지름에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"지아 — 「한 원에 반지름은 1개입니다.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"}],"explanation":["한 원에 원의 중심은 1개예요.","반지름은 무수히 많아요.","지아의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#18','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',3,'sa','auto','「추론」 — 그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u3-C3","difficulty":3,"kind":"sa","stem":"「추론」 — 그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심 가까이를 지나도 중심을 지나지 않는 선분, 중심에서 시작하는 반지름은 빼요.","지름은 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㅁ":[85.1,100.7,"s"],"ㅈ":[97.4,31.1,"ne"],"ㄹ":[52.6,94.9,"sw"],"ㄷ":[36.1,66.4,"w"],"ㅅ":[113.9,59.6,"e"],"ㄴ":[41.9,42.3,"nw"],"ㅂ":[112.1,75.1,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅁ"],["ㅈ","ㄹ"],["ㄷ","ㅅ"],["ㄴ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#19','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',3,'mc','auto','점 ㅇ은 원의 중심이에요. 그림의 선분은 원 위의 두 점을 이은 8 cm, 6 cm 선분과 반지름 7 cm예요. 이 원에서 원 위의 두 점을 이은 선분 가운데 가장 긴 선분은 몇 cm인가요?',ARRAY['M3-2-u3-X17','M3-2-u3-X09','M3-2-u3-X15']::text[],false,'{"seq":19,"concept":"M3-2-u3-C5","difficulty":3,"kind":"mc","stem":"점 ㅇ은 원의 중심이에요. 그림의 선분은 원 위의 두 점을 이은 8 cm, 6 cm 선분과 반지름 7 cm예요. 이 원에서 원 위의 두 점을 이은 선분 가운데 가장 긴 선분은 몇 cm인가요?","options":[{"t":"14 cm","correct":true},{"t":"8 cm","mis":"M3-2-u3-X17"},{"t":"7 cm","mis":"M3-2-u3-X09"},{"t":"15 cm","mis":"M3-2-u3-X15"}],"explanation":["원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요.","지름 = 7 × 2 = 14(cm).","8 cm 선분은 원의 중심을 지나지 않아 지름보다 짧아요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㄴ":[37.3,52.9,"w"],"ㄷ":[113.9,59.6,"e"],"ㄹ":[49.9,92.9,"sw"],"ㅁ":[85.1,100.7,"s"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅁ"]],"lab":[[[39.5,27.5],"8 cm"],[[98.3,51.6],"7 cm"],[[64.1,112.1],"6 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#20','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',3,'sa','auto','주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 작은 원의 중심에서 가장 큰 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 작은 원의 중심에서 가장 큰 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원 3개의 반지름은 2칸, 3칸, 4칸이고 모두 왼쪽 한 점에서 만나요.","만나는 점에서 중심까지가 반지름 — 2칸, 3칸, 4칸 떨어져 있어요.","4 − 2 = 2칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#21','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C7',3,'sa','auto','원이 맞닿게 이어진 그림이에요. 점 ㄱ에서 점 ㅅ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"원이 맞닿게 이어진 그림이에요. 점 ㄱ에서 점 ㅅ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["1 + 2 + 2 + 3 + 3 + 4를 더해요.","반지름·지름이 차례로 이어져 있어요.","15칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#22','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',3,'ox','auto','「반지름이 5 cm인 원과 지름이 10 cm인 원은 크기가 같아요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X10']::text[],false,'{"seq":22,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"「반지름이 5 cm인 원과 지름이 10 cm인 원은 크기가 같아요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름 5 cm인 원의 지름도 10 cm라서","correct":true},{"t":"적힌 수가 달라서 크기도 달라서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["5 × 2 = 10(cm).","두 원의 지름이 같아요.","크기가 같아요(O)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#23','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',4,'sa','auto','「추론」 — 이 원의 지름은 3 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"「추론」 — 이 원의 지름은 3 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 3개예요.","한 원에서 지름은 모두 3 cm예요.","3 + 3 + 3 = 9(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㅁ":[85.1,100.7,"s"],"ㅈ":[97.4,31.1,"ne"],"ㄹ":[52.6,94.9,"sw"],"ㄷ":[36.1,66.4,"w"],"ㅅ":[113.9,59.6,"e"],"ㄴ":[41.9,42.3,"nw"],"ㅂ":[112.1,75.1,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㅁ"],["ㅈ","ㄹ"],["ㄷ","ㅅ"],["ㄴ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#24','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',4,'sa','auto','「수학에 퐁당」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ을 모두 지나는 원을 컴퍼스로 그리려고 해요. 세 점과 같은 거리에 있는 점을 원의 중심으로 하면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u3-C6","difficulty":4,"kind":"sa","stem":"「수학에 퐁당」 — 모눈 위의 세 점 ㄱ, ㄴ, ㄷ을 모두 지나는 원을 컴퍼스로 그리려고 해요. 세 점과 같은 거리에 있는 점을 원의 중심으로 하면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["세 점과 같은 거리에 있는 점은 점 ㄱ에서 아래로 2칸인 점이에요.","그 점에서 ㄱ, ㄴ, ㄷ까지 모두 2칸이에요.","2칸만큼 벌려요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":15,"pts":{"ㄱ":[45,15,"n"],"ㄴ":[15,45,"w"],"ㄷ":[75,45,"e"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_a#25','math',3,2,'u3','','tb_g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',4,'essay','teacher','「서술형」 — 건우는 지름이 2 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 자의 눈금 0과 2에 맞추어 벌렸어요. 이렇게 벌린 것이 옳은지 쓰고, 그 이유를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C6","difficulty":4,"kind":"essay","stem":"「서술형」 — 건우는 지름이 2 cm인 원을 그리려고 컴퍼스의 침과 연필의 끝부분을 자의 눈금 0과 2에 맞추어 벌렸어요. 이렇게 벌린 것이 옳은지 쓰고, 그 이유를 써 보세요.","answer_guide":{"answer":"예: 옳지 않다. 지름이 2 cm인 원을 그리기 위해서는 컴퍼스를 반지름인 1 cm만큼 벌려야 하는데 2 cm만큼 벌렸기 때문이다. 2 cm만큼 벌리면 지름이 4 cm인 원이 그려진다.","scoring_points":["옳지 않다고 답했는가","컴퍼스는 반지름(1 cm)만큼 벌려야 한다고 썼는가","2 cm 벌리면 지름 4 cm인 원이 된다는 것을 알았는가"]},"explanation":["컴퍼스를 벌린 길이 = 반지름.","지름 2 cm인 원의 반지름은 1 cm.","2 cm만큼 벌리면 지름 4 cm인 원이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#1','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',1,'mc','auto','「빈칸을 채우세요」 — 원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 원의 무엇인가요?',ARRAY['M3-2-u3-X17','M3-2-u3-X03','M3-2-u3-X02']::text[],false,'{"seq":1,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"「빈칸을 채우세요」 — 원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X17"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분을 여러 개 그어 봐요.","가장 긴 선분은 원의 중심을 지나요.","그 선분이 지름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#2','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',1,'mc','auto','「스스로 마무리하기」 — 그림에서 원의 반지름은 어느 선분인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X20']::text[],false,'{"seq":2,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 그림에서 원의 반지름은 어느 선분인가요?","options":[{"t":"선분 ㅇㄷ","correct":true},{"t":"선분 ㄹㅂ","mis":"M3-2-u3-X07"},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X20"},{"t":"선분 ㅁㅅ","mis":"M3-2-u3-X20"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이은 선분이에요.","선분 ㄹㅂ은 지름, 선분 ㄱㄴ·ㅁㅅ은 원의 중심과 이어지지 않았어요.","반지름은 선분 ㅇㄷ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㄴ":[85.1,25.3,"n"],"ㄷ":[64.9,100.7,"s"],"ㄹ":[94.5,96.8,"se"],"ㅁ":[104.9,37.9,"ne"],"ㅂ":[55.5,29.2,"nw"],"ㅅ":[108.8,82.5,"se"],"ㅇ":[75,63.0,"ne"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅂ"],["ㅁ","ㅅ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#3','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',1,'sa','auto','원에 지름을 여러 개 긋고 재었더니 지름 하나가 6 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"원에 지름을 여러 개 긋고 재었더니 지름 하나가 6 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#4','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C4',1,'mc','auto','「스스로 마무리하기」 — 점 ㅇ은 원의 중심이에요. 그림에 8 cm, 6 cm 선분과 반지름 7 cm가 있어요. 이 원의 지름은 몇 cm인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X09']::text[],false,'{"seq":4,"concept":"M3-2-u3-C4","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 점 ㅇ은 원의 중심이에요. 그림에 8 cm, 6 cm 선분과 반지름 7 cm가 있어요. 이 원의 지름은 몇 cm인가요?","options":[{"t":"14 cm","correct":true},{"t":"8 cm","mis":"M3-2-u3-X06"},{"t":"7 cm","mis":"M3-2-u3-X09"},{"t":"6 cm","mis":"M3-2-u3-X06"}],"explanation":["원의 중심에서 그은 7 cm 선분이 반지름이에요.","지름은 반지름의 2배예요.","7 × 2 = 14 — 지름은 14 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[64.9,25.3,"n"],"ㄴ":[37.3,52.9,"w"],"ㄷ":[113.9,59.6,"e"],"ㄹ":[49.9,92.9,"sw"],"ㅁ":[85.1,100.7,"s"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅁ"]],"lab":[[[39.5,27.5],"8 cm"],[[98.3,51.6],"7 cm"],[[64.1,112.1],"6 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#5','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',1,'mc','auto','「확인 문제」 — 원에 대해 옳게 설명한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X21']::text[],false,'{"seq":5,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"「확인 문제」 — 원에 대해 옳게 설명한 사람은 누구인가요?","options":[{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","correct":true},{"t":"나은 — 「한 원에 지름은 1개입니다.」","mis":"M3-2-u3-X04"},{"t":"지아 — 「한 원에 반지름은 1개입니다.」","mis":"M3-2-u3-X04"},{"t":"지유 — 「원의 중심은 원을 똑같이 둘로 나눠.」","mis":"M3-2-u3-X21"}],"explanation":["반지름은 원 위의 점마다 그을 수 있어요.","한 원에 반지름·지름은 무수히 많아요.","옳게 설명한 사람은 가람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#6','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',1,'mc','auto','「크기가 가장 큰 원」 — 크기가 가장 큰 원을 찾아 기호를 쓰세요. (㉠ 반지름이 5 cm인 원, ㉡ 반지름이 6 cm인 원, ㉢ 지름이 10 cm인 원)',ARRAY['M3-2-u3-X10','M3-2-u3-X09']::text[],false,'{"seq":6,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"「크기가 가장 큰 원」 — 크기가 가장 큰 원을 찾아 기호를 쓰세요. (㉠ 반지름이 5 cm인 원, ㉡ 반지름이 6 cm인 원, ㉢ 지름이 10 cm인 원)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X10"},{"t":"모두 같아요","mis":"M3-2-u3-X09"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 10 cm, ㉡ 지름 12 cm, ㉢ 지름 10 cm.","크기가 가장 큰 원은 ㉡이에요 — 적힌 수만 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#7','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',1,'ox','auto','「지름이 4 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 2 cm만큼 벌려요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X11']::text[],false,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"ox","stem":"「지름이 4 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 2 cm만큼 벌려요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름은 지름의 반인 2 cm라서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"mis":"M3-2-u3-X11","explanation":["지름이 주어지면 반으로 나누어 반지름을 구해요.","4의 반은 2 — 반지름은 2 cm예요.","2 cm만큼 벌려요(O)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#8','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',1,'mc','auto','「주어진 모양과 똑같이」 — 원 3개가 왼쪽 한 점에서 만나는 모양을 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],false,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「주어진 모양과 똑같이」 — 원 3개가 왼쪽 한 점에서 만나는 모양을 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"6군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 3개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 3군데예요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#9','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C4',2,'sa','auto','「이 단원 학습을 마치고」 — 만화의 큰 피자는 지름이 약 30 cm예요. 이 피자의 반지름은 약 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"「이 단원 학습을 마치고」 — 만화의 큰 피자는 지름이 약 30 cm예요. 이 피자의 반지름은 약 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["한 원에서 반지름은 지름의 반이에요.","30의 반은 15예요.","반지름은 약 15 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#10','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C8',2,'sa','auto','원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C8","difficulty":2,"kind":"sa","stem":"원 2개를 맞닿게 그려 눈사람을 그렸어요. 작은 원의 반지름은 2 cm, 큰 원의 반지름은 5 cm예요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["선분 ㄱㄴ은 두 원의 반지름을 이은 것이에요.","2 cm + 5 cm.","2 + 5 = 7(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":141.0,"circle":[[[52.5,33.0],15.0],[[52.5,85.5],37.5]],"pts":{"ㄱ":[52.5,33.0,"e"],"ㄴ":[52.5,85.5,"e"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#11','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C4',2,'mc','auto','「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 5 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],false,'{"seq":11,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 5 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 10 cm인 원","correct":true},{"t":"지름이 5 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 10 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 20 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 5 cm인 원의 지름은 5 × 2 = 10(cm)예요.","그래서 「지름이 10 cm인 원」 카드와 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#12','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',2,'sa','auto','「확인 문제」 — 지름이 2 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"「확인 문제」 — 지름이 2 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 2 cm의 반은 1 cm예요.","1 cm만큼 벌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#13','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C1',2,'mc','auto','원 위의 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],false,'{"seq":13,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄱ만 선 위에 있어요. 점 ㄷ은 원 안, 점 ㄴ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[39.8,50.2,"w"],"ㄷ":[83.4,77.6,"se"],"ㄴ":[93.0,13.7,"n"]},"circle":[[[75,63.0],37.5]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#14','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',2,'mc','auto','누름 못은 구멍 ㄴ에, 연필은 구멍 ㄷ에 꽂아 원을 그렸어요. 원을 더 크게 그리려면 연필을 어디에 꽂아야 하나요?',ARRAY['M3-2-u3-X24','M3-2-u3-X12']::text[],false,'{"seq":14,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"누름 못은 구멍 ㄴ에, 연필은 구멍 ㄷ에 꽂아 원을 그렸어요. 원을 더 크게 그리려면 연필을 어디에 꽂아야 하나요?","options":[{"t":"구멍 ㅁ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X24"},{"t":"구멍 ㄴ","mis":"M3-2-u3-X12"},{"t":"구멍 ㄷ 그대로","mis":"M3-2-u3-X24"}],"explanation":["누름 못에서 연필까지가 반지름이에요.","더 먼 구멍에 연필을 꽂으면 반지름이 길어져요.","구멍 ㅁ에 꽂으면 원이 더 커져요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[107.6,47.8,"ne"],"ㅁ":[123.9,40.2,"ne"],"ㄱ":[55.9,57.9,"nw"],"ㄹ":[102.6,86.1,"se"],"ㄴ":[75,63.0,"sw"]},"circle":[[[75,63.0],36.0]],"seg":[["ㄴ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#15','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C7',2,'sa','auto','이 규칙에 맞게 원을 더 그릴 때, 넷째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"이 규칙에 맞게 원을 더 그릴 때, 넷째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원의 중심은 오른쪽으로 2칸씩 옮겨 가요.","넷째 원의 중심에서 오른쪽으로 2칸이에요.","2칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#16','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',2,'mc','auto','원 모양의 종이가 똑같이 둘로 나누어지도록 접었다 폈어요. 접었다 폈을 때 생기는 선분은 원의 무엇인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X21','M3-2-u3-X02']::text[],false,'{"seq":16,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"원 모양의 종이가 똑같이 둘로 나누어지도록 접었다 폈어요. 접었다 폈을 때 생기는 선분은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X21"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","원 위의 두 점을 이으면서 원의 중심을 지나는 선분이에요.","그래서 지름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#17','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',3,'error','auto','원에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X16']::text[],false,'{"seq":17,"concept":"M3-2-u3-C3","difficulty":3,"kind":"error","stem":"원에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"나은 — 「한 원에 지름은 1개입니다.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"은비 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 원의 지름이야.」","mis":"M3-2-u3-X16"}],"explanation":["한 원에 지름은 무수히 많아요.","나머지 세 사람의 말은 맞아요.","나은이의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#18','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',3,'sa','auto','그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u3-C3","difficulty":3,"kind":"sa","stem":"그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심 가까이를 지나도 중심을 지나지 않는 선분, 중심에서 시작하는 반지름은 빼요.","지름은 3개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[114.0,63.0,"e"],"ㄴ":[36.0,63.0,"w"],"ㄷ":[94.5,29.2,"ne"],"ㄹ":[55.5,96.8,"sw"],"ㅁ":[55.5,29.2,"nw"],"ㅂ":[94.5,96.8,"se"],"ㅅ":[38.4,76.3,"w"],"ㅈ":[81.8,101.4,"s"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#19','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',3,'mc','auto','「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?',ARRAY['M3-2-u3-X20','M3-2-u3-X08']::text[],false,'{"seq":19,"concept":"M3-2-u3-C2","difficulty":3,"kind":"mc","stem":"「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?","options":[{"t":"5 cm","correct":true},{"t":"3 cm","mis":"M3-2-u3-X20"},{"t":"7 cm","mis":"M3-2-u3-X20"},{"t":"10 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이은 선분이에요.","원의 중심과 이어지지 않은 선분(3 cm, 7 cm)은 반지름이 아니에요.","중심에서 그은 선분이 5 cm — 반지름은 5 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[41.2,43.5,"nw"],"ㄴ":[52.6,31.1,"nw"],"ㄷ":[36.1,59.6,"w"],"ㄹ":[75.0,24.0,"n"],"ㅁ":[75.0,102.0,"s"],"ㅂ":[39.7,79.5,"sw"],"ㅅ":[112.7,73.1,"e"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㅇ","ㄱ"],["ㄴ","ㄷ"],["ㄹ","ㅁ"],["ㅂ","ㅅ"]],"lab":[[[49.4,59.0],"5 cm"],[[31.5,37.9],"3 cm"],[[79.4,113.1],"7 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#20','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',3,'sa','auto','주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 큰 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가장 큰 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["가장 큰 원의 반지름을 모눈으로 세면 4칸이에요.","한 원에서 지름은 반지름의 2배예요.","4 × 2 = 8칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#21','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C7',3,'sa','auto','이 규칙에 맞게 원을 2개 더 그렸어요. 첫째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그렸어요. 첫째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["중심은 오른쪽으로 2칸씩 옮겨 가요.","4번 옮겨요.","2 × 4 = 8칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#22','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',3,'ox','auto','「지름이 4 cm인 원과 반지름이 4 cm인 원은 크기가 같아요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X10']::text[],false,'{"seq":22,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"「지름이 4 cm인 원과 반지름이 4 cm인 원은 크기가 같아요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"반지름이 4 cm인 원은 지름이 8 cm라서","correct":true},{"t":"적힌 수가 같으면 크기도 같아서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["4 × 2 = 8(cm).","지름 8 cm인 원이 더 커요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#23','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',4,'sa','auto','원에 지름을 여러 개 그었어요. 이 원의 지름은 6 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"원에 지름을 여러 개 그었어요. 이 원의 지름은 6 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 3개예요.","한 원에서 지름은 모두 6 cm예요.","6 + 6 + 6 = 18(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[114.0,63.0,"e"],"ㄴ":[36.0,63.0,"w"],"ㄷ":[94.5,29.2,"ne"],"ㄹ":[55.5,96.8,"sw"],"ㅁ":[55.5,29.2,"nw"],"ㅂ":[94.5,96.8,"se"],"ㅅ":[38.4,76.3,"w"],"ㅈ":[81.8,101.4,"s"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#24','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C7',4,'sa','auto','이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u3-C7","difficulty":4,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["첫째 원의 왼쪽 끝은 첫째 중심에서 1칸 왼쪽.","여섯째 원의 중심은 10칸 오른쪽, 반지름 2칸.","1 + 10 + 2 = 13칸이에요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_b#25','math',3,2,'u3','','tb_g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',4,'essay','teacher','「추론」 — 반지름이 4 cm인 원 ㉡과 지름이 6 cm인 원 ㉠ 가운데 어느 원이 더 큰지 쓰고, 그 까닭을 지름과 반지름의 관계를 써서 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C5","difficulty":4,"kind":"essay","stem":"「추론」 — 반지름이 4 cm인 원 ㉡과 지름이 6 cm인 원 ㉠ 가운데 어느 원이 더 큰지 쓰고, 그 까닭을 지름과 반지름의 관계를 써서 설명해 보세요.","answer_guide":{"answer":"예: ㉡이 더 크다. 한 원에서 지름은 반지름의 2배이므로 ㉡의 지름은 4 × 2 = 8(cm)이다. ㉠의 지름은 6 cm이므로 지름을 견주면 8 cm가 6 cm보다 길어서 ㉡이 더 크다.","scoring_points":["㉡이 더 크다고 답했는가","지름은 반지름의 2배라는 관계를 썼는가","같은 기준으로 바꾸어 견주었는가"]},"explanation":["한 가지(지름)로 바꾸어요.","㉡의 지름 = 4 × 2 = 8 cm.","8 cm > 6 cm — ㉡이 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#1','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',1,'mc','auto','「빈칸을 채우세요」 — 컴퍼스를 이용하여 원을 그릴 때 ①에 들어갈 말은 무엇인가요? (① 원의 □이/가 되는 점을 정합니다.)',ARRAY['M3-2-u3-X12']::text[],false,'{"seq":1,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「빈칸을 채우세요」 — 컴퍼스를 이용하여 원을 그릴 때 ①에 들어갈 말은 무엇인가요? (① 원의 □이/가 되는 점을 정합니다.)","options":[{"t":"중심","correct":true},{"t":"반지름","mis":"M3-2-u3-X12"},{"t":"지름","mis":"M3-2-u3-X12"},{"t":"끝","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요.","③ 컴퍼스의 침을 원의 중심에 꽂고 돌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#2','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',1,'mc','auto','「스스로 마무리하기」 — 그림에서 원의 지름은 어느 선분인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X07']::text[],false,'{"seq":2,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 — 그림에서 원의 지름은 어느 선분인가요?","options":[{"t":"선분 ㄹㅂ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅅ","mis":"M3-2-u3-X06"},{"t":"선분 ㅇㄷ","mis":"M3-2-u3-X07"}],"explanation":["지름은 원 위의 두 점을 이은 선분이 원의 중심을 지날 때의 선분이에요.","선분 ㄱㄴ, ㅁㅅ은 원의 중심을 지나지 않고, 선분 ㅇㄷ은 반지름이에요.","지름은 선분 ㄹㅂ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[68.2,101.4,"s"],"ㄴ":[47.4,35.4,"nw"],"ㄷ":[102.6,90.6,"se"],"ㄹ":[114.0,63.0,"e"],"ㅁ":[68.2,24.6,"n"],"ㅂ":[36.0,63.0,"w"],"ㅅ":[108.8,43.5,"ne"],"ㅇ":[75,63.0,"n"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅂ"],["ㅁ","ㅅ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#3','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',1,'sa','auto','「안에 알맞은 수」 — 원에 그은 지름 하나가 8 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"「안에 알맞은 수」 — 원에 그은 지름 하나가 8 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#4','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C2',1,'mc','auto','「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?',ARRAY['M3-2-u3-X20','M3-2-u3-X08']::text[],false,'{"seq":4,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"「반지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 반지름은 몇 cm인가요?","options":[{"t":"4 cm","correct":true},{"t":"6 cm","mis":"M3-2-u3-X20"},{"t":"5 cm","mis":"M3-2-u3-X20"},{"t":"8 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이은 선분이에요.","원의 중심과 이어지지 않은 선분(6 cm, 5 cm)은 반지름이 아니에요.","중심에서 그은 선분이 4 cm — 반지름은 4 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[49.9,33.1,"nw"],"ㄴ":[100.1,33.1,"ne"],"ㄷ":[81.8,101.4,"s"],"ㄹ":[113.9,65.0,"e"],"ㅁ":[37.3,52.9,"w"],"ㅇ":[75,63.0,"e"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅇ","ㅁ"]],"lab":[[[75.0,12.8],"6 cm"],[[112.6,96.3],"5 cm"],[[49.2,65.7],"4 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#5','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',1,'mc','auto','원에 대해 바르게 설명한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X17']::text[],false,'{"seq":5,"concept":"M3-2-u3-C4","difficulty":1,"kind":"mc","stem":"원에 대해 바르게 설명한 사람은 누구인가요?","options":[{"t":"서윤 — 「반지름은 지름의 반이야.」","correct":true},{"t":"정후 — 「원을 똑같이 둘로 나눌 수 있는 선분은 1개야.」","mis":"M3-2-u3-X04"},{"t":"현수 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 반지름이야.」","mis":"M3-2-u3-X17"},{"t":"건우 — 「한 원에 반지름은 2개 그을 수 있어.」","mis":"M3-2-u3-X04"}],"explanation":["원을 똑같이 둘로 나누는 선분(지름)은 무수히 많아요.","가장 긴 선분은 지름이에요.","바르게 설명한 사람은 서윤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#6','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C5',1,'mc','auto','크기가 가장 작은 원을 찾아 기호를 쓰세요. (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)',ARRAY['M3-2-u3-X10']::text[],false,'{"seq":6,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"크기가 가장 작은 원을 찾아 기호를 쓰세요. (㉠ 지름이 6 cm인 원, ㉡ 반지름이 4 cm인 원, ㉢ 반지름이 6 cm인 원, ㉣ 지름이 4 cm인 원)","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉡","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 8 cm, ㉢ 지름 12 cm, ㉣ 지름 4 cm.","크기가 가장 작은 원은 ㉣이에요 — 적힌 수만 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#7','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',1,'ox','auto','「반지름이 3 cm인 원을 그리려면 컴퍼스를 6 cm만큼 벌려요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X08']::text[],false,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"ox","stem":"「반지름이 3 cm인 원을 그리려면 컴퍼스를 6 cm만큼 벌려요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"컴퍼스를 벌린 길이가 반지름이라 3 cm만큼 벌려야 해서","correct":true},{"t":"컴퍼스는 반지름의 2배만큼 벌려서","mis":"M3-2-u3-X08"}],"mis":"M3-2-u3-X08","explanation":["컴퍼스의 침과 연필 끝 사이의 거리가 반지름이에요.","반지름 3 cm인 원은 3 cm만큼 벌려요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#8','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',1,'mc','auto','같은 점을 중심으로 그린 원 3개를 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],false,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"같은 점을 중심으로 그린 원 3개를 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"1군데","correct":true},{"t":"3군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 3개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 1군데예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],45],[[60,60],30],[[60,60],15]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#9','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',2,'sa','auto','「드림캐처」 — 큰 드림캐처에 그어진 반지름을 재었더니 2 cm였어요. 이 드림캐처의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"「드림캐처」 — 큰 드림캐처에 그어진 반지름을 재었더니 2 cm였어요. 이 드림캐처의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 원에서 지름은 반지름의 2배예요.","2 × 2 = 4예요.","지름은 4 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#10','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',2,'sa','auto','원 2개를 맞닿게 그려 눈사람을 그렸어요. 큰 원의 반지름이 5 cm일 때 큰 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"원 2개를 맞닿게 그려 눈사람을 그렸어요. 큰 원의 반지름이 5 cm일 때 큰 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["한 원에서 지름은 반지름의 2배예요.","5 × 2 = 10이에요.","큰 원의 지름은 10 cm예요."],"asset":{"type":"geo","items":[{"w":105,"h":141.0,"circle":[[[52.5,33.0],15.0],[[52.5,85.5],37.5]],"pts":{"ㄱ":[52.5,33.0,"e"],"ㄴ":[52.5,85.5,"e"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#11','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',2,'mc','auto','「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 3 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],false,'{"seq":11,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 3 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 6 cm인 원","correct":true},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 6 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 12 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 3 cm인 원의 지름은 3 × 2 = 6(cm)예요.","그래서 「지름이 6 cm인 원」 카드와 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#12','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',2,'sa','auto','지름이 8 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"지름이 8 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 8 cm의 반은 4 cm예요.","4 cm만큼 벌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#13','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C1',2,'mc','auto','원 위의 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],false,'{"seq":13,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄷ만 선 위에 있어요. 점 ㄴ은 원 안, 점 ㄱ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[68.5,99.9,"s"],"ㄴ":[87.9,52.2,"ne"],"ㄱ":[23.3,53.9,"w"]},"circle":[[[75,63.0],37.5]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#14','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C2',2,'mc','auto','포이를 돌릴 때 줄의 길이를 길게 하면 만들어지는 원의 크기는 어떻게 되나요?',ARRAY['M3-2-u3-X24','M3-2-u3-X23']::text[],false,'{"seq":14,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"포이를 돌릴 때 줄의 길이를 길게 하면 만들어지는 원의 크기는 어떻게 되나요?","options":[{"t":"커져요","correct":true},{"t":"작아져요","mis":"M3-2-u3-X24"},{"t":"그대로예요","mis":"M3-2-u3-X24"},{"t":"원이 생기지 않아요","mis":"M3-2-u3-X23"}],"explanation":["줄을 잡은 손이 원의 중심이에요.","줄이 길면 공이 손에서 더 멀리 떨어져 돌아요.","그래서 원이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#15','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C7',2,'sa','auto','「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림이에요. 점 ㅁ을 원의 중심으로 하는 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"「수학과 교구 및 공학 도구」 — 원이 맞닿게 이어진 그림이에요. 점 ㅁ을 원의 중심으로 하는 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㅁ은 셋째 원의 중심이에요.","점 ㅁ에서 점 ㄹ까지 칸을 세요.","3칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#16','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C5',2,'mc','auto','점 ㄱ에서 그은 선분 가운데 길이가 가장 긴 선분은 어느 것인가요?',ARRAY['M3-2-u3-X17']::text[],false,'{"seq":16,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"점 ㄱ에서 그은 선분 가운데 길이가 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄹ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","그중 원의 중심 ㅇ을 지나는 선분 ㄱㄷ이 지름이에요.","원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[61.7,26.4,"n"],"ㄷ":[41.2,82.5,"sw"],"ㄹ":[68.2,101.4,"s"],"ㅁ":[104.9,88.1,"se"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#17','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C5',3,'error','auto','원에 대해 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X21','M3-2-u3-X16']::text[],false,'{"seq":17,"concept":"M3-2-u3-C5","difficulty":3,"kind":"error","stem":"원에 대해 잘못 말한 사람은 누구인가요?","options":[{"t":"지유 — 「원의 중심은 원을 똑같이 둘로 나눠.」","correct":true,"mis_target":"M3-2-u3-X21"},{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「한 원에 반지름은 무수히 많습니다.」","mis":"M3-2-u3-X16"},{"t":"은비 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 원의 지름이야.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 점이에요.","원을 똑같이 둘로 나누는 것은 지름이에요.","지유의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#18','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',3,'sa','auto','그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u3-C3","difficulty":3,"kind":"sa","stem":"그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심 가까이를 지나도 중심을 지나지 않는 선분, 중심에서 시작하는 반지름은 빼요.","지름은 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[41.2,82.5,"sw"],"ㄷ":[75.0,24.0,"n"],"ㄹ":[75.0,102.0,"s"],"ㅁ":[49.9,33.1,"nw"],"ㅂ":[36.0,63.0,"w"],"ㅅ":[94.5,96.8,"se"],"ㅈ":[113.4,69.8,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#19','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',3,'mc','auto','「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X06']::text[],false,'{"seq":19,"concept":"M3-2-u3-C3","difficulty":3,"kind":"mc","stem":"「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?","options":[{"t":"12 cm","correct":true},{"t":"6 cm","mis":"M3-2-u3-X07"},{"t":"8 cm","mis":"M3-2-u3-X06"},{"t":"24 cm","mis":"M3-2-u3-X07"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","원의 중심을 지나지 않는 선분의 길이는 지름이 아니에요.","원의 중심을 지나는 선분이 12 cm — 지름은 12 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[81.8,24.6,"n"],"ㄴ":[68.2,101.4,"s"],"ㄷ":[111.6,49.7,"e"],"ㄹ":[38.4,76.3,"w"],"ㅁ":[88.3,99.6,"s"],"ㅇ":[75,63.0,"w"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"],["ㄹ","ㅁ"]],"lab":[[[82.3,82.1],"12 cm"],[[94.5,46.0],"6 cm"],[[53.8,108.5],"8 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#20','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',3,'sa','auto','주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가운데 크기 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"주어진 모양은 원 3개가 왼쪽 한 점에서 만나요. 가운데 크기 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가운데 크기 원의 중심을 찾아요.","원의 중심에서 원 위의 점(왼쪽 만나는 점)까지 칸을 세요.","반지름은 3칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[45,75],30],[[60,75],45],[[75,75],60]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#21','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C7',3,'sa','auto','같은 점을 원의 중심으로 하여 반지름이 모눈 3칸, 2칸, 1칸인 원을 그렸어요. 가장 큰 원의 지름은 가장 작은 원의 지름보다 모눈 몇 칸 더 긴가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"같은 점을 원의 중심으로 하여 반지름이 모눈 3칸, 2칸, 1칸인 원을 그렸어요. 가장 큰 원의 지름은 가장 작은 원의 지름보다 모눈 몇 칸 더 긴가요? 숫자로 쓰세요.","answer":["4"],"explanation":["지름은 반지름의 2배예요.","6칸 − 2칸.","4칸이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],45],[[60,60],30],[[60,60],15]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#22','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C5',3,'ox','auto','「반지름이 6 cm인 원은 지름이 6 cm인 원보다 커요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X10']::text[],false,'{"seq":22,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"「반지름이 6 cm인 원은 지름이 6 cm인 원보다 커요.」 이 말이 맞나요?","answer":"O","reason_options":[{"t":"반지름 6 cm인 원의 지름은 12 cm라서","correct":true},{"t":"적힌 수가 같으면 크기도 같아서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["6 × 2 = 12(cm).","12 cm > 6 cm.","맞는 말이에요(O)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#23','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',4,'sa','auto','「안에 알맞은 수」 — 이 원의 지름은 8 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"「안에 알맞은 수」 — 이 원의 지름은 8 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 2개예요.","한 원에서 지름은 모두 8 cm예요.","8 + 8 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[108.8,43.5,"ne"],"ㄴ":[41.2,82.5,"sw"],"ㄷ":[75.0,24.0,"n"],"ㄹ":[75.0,102.0,"s"],"ㅁ":[49.9,33.1,"nw"],"ㅂ":[36.0,63.0,"w"],"ㅅ":[94.5,96.8,"se"],"ㅈ":[113.4,69.8,"e"],"ㅇ":[75,63.0,"se"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#24','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',4,'sa','auto','반지름이 4 cm인 원과 지름이 4 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때, 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u3-C4","difficulty":4,"kind":"sa","stem":"반지름이 4 cm인 원과 지름이 4 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때, 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["반지름 4 cm인 원의 지름은 8 cm예요.","다른 원의 지름은 4 cm예요.","8 + 4 = 12(cm)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_c#25','math',3,2,'u3','','tb_g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',4,'essay','teacher','「서술형」 — 원 위의 두 점을 이은 선분이 지름인지 알아보려고 해요. 어떻게 확인하면 되는지 쓰고, 지름이라면 이 원의 반지름은 그 선분과 어떤 관계인지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C3","difficulty":4,"kind":"essay","stem":"「서술형」 — 원 위의 두 점을 이은 선분이 지름인지 알아보려고 해요. 어떻게 확인하면 되는지 쓰고, 지름이라면 이 원의 반지름은 그 선분과 어떤 관계인지 써 보세요.","answer_guide":{"answer":"예: 원의 중심에 자를 대어 선분이 원의 중심을 지나는지 확인한다. 중심을 지나면 지름이다. 지름이라면 반지름은 그 선분 길이의 반이다.","scoring_points":["원의 중심을 지나는지 확인한다고 썼는가","중심을 지나면 지름이라고 썼는가","반지름은 지름의 반이라고 썼는가"]},"explanation":["지름은 원의 중심을 지나요.","원의 중심에 자를 대어 확인해요.","반지름 = 지름의 반."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#1','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',1,'mc','auto','「빈칸을 채우세요」 — 컴퍼스를 이용하여 원을 그릴 때 ②에 들어갈 말은 무엇인가요? (② 컴퍼스의 침과 연필의 끝부분을 □만큼 벌립니다.)',ARRAY['M3-2-u3-X11','M3-2-u3-X12']::text[],false,'{"seq":1,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「빈칸을 채우세요」 — 컴퍼스를 이용하여 원을 그릴 때 ②에 들어갈 말은 무엇인가요? (② 컴퍼스의 침과 연필의 끝부분을 □만큼 벌립니다.)","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X11"},{"t":"원의 중심","mis":"M3-2-u3-X12"},{"t":"원 위의 점","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 컴퍼스의 침과 연필의 끝부분을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 돌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#2','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C2',1,'mc','auto','「확인 문제」 — 원의 중심을 찾아 기호를 쓰세요.',ARRAY['M3-2-u3-X03']::text[],false,'{"seq":2,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"「확인 문제」 — 원의 중심을 찾아 기호를 쓰세요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X03"},{"t":"㉢","mis":"M3-2-u3-X03"},{"t":"㉣","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원의 가장 안쪽에 있는 한 점이에요.","㉠은 원 위의 점, ㉢은 원 안의 다른 점, ㉣은 원 밖의 점이에요.","원의 중심은 ㉡이에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"circle":[[[75,63.0],39.0]],"pts":{"㉠":[52.6,31.1,"nw"],"㉡":[75,63.0,"sw"],"㉢":[95.3,68.4,"se"],"㉣":[27.1,80.4,"w"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#3','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C3',1,'sa','auto','「추론」 — 원에 그은 지름 하나가 3 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"「추론」 — 원에 그은 지름 하나가 3 cm였어요. 이 원에 그은 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 원에는 지름을 무수히 많이 그을 수 있어요.","원에 그은 지름을 재어 비교하면 길이가 모두 같아요.","다른 지름도 3 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#4','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C3',1,'mc','auto','「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X07']::text[],false,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"「지름을 구해 보세요」 — 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요?","options":[{"t":"7 cm","correct":true},{"t":"5 cm","mis":"M3-2-u3-X06"},{"t":"6 cm","mis":"M3-2-u3-X06"},{"t":"14 cm","mis":"M3-2-u3-X07"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","원의 중심을 지나지 않는 선분의 길이는 지름이 아니에요.","원의 중심을 지나는 선분이 7 cm — 지름은 7 cm예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[38.4,76.3,"w"],"ㄴ":[68.2,24.6,"n"],"ㄷ":[111.6,49.7,"e"],"ㄹ":[108.8,82.5,"se"],"ㅇ":[75,63.0,"s"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"]],"lab":[[[31.5,37.9],"5 cm"],[[87.9,47.1],"7 cm"],[[70.6,113.1],"6 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#5','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C2',1,'mc','auto','원에 대해 바르게 설명한 사람은 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X17']::text[],false,'{"seq":5,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"원에 대해 바르게 설명한 사람은 누구인가요?","options":[{"t":"민준 — 「한 원에 원의 중심은 1개입니다.」","correct":true},{"t":"지아 — 「한 원에 반지름은 1개입니다.」","mis":"M3-2-u3-X04"},{"t":"나은 — 「한 원에 지름은 1개입니다.」","mis":"M3-2-u3-X04"},{"t":"현수 — 「원 위의 두 점을 이은 선분 중에서 길이가 가장 긴 선분은 반지름이야.」","mis":"M3-2-u3-X17"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점 — 한 원에 1개예요.","반지름과 지름은 무수히 많아요.","바르게 설명한 사람은 민준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#6','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C4',1,'mc','auto','「크기가 같은 원」 — 지름이 4 cm인 원과 크기가 같은 원은 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],false,'{"seq":6,"concept":"M3-2-u3-C4","difficulty":1,"kind":"mc","stem":"「크기가 같은 원」 — 지름이 4 cm인 원과 크기가 같은 원은 어느 것인가요?","options":[{"t":"반지름이 2 cm인 원","correct":true},{"t":"반지름이 4 cm인 원","mis":"M3-2-u3-X09"},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X08"},{"t":"반지름이 8 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 2 cm인 원의 지름은 2 × 2 = 4(cm)예요.","그래서 크기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#7','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',1,'ox','auto','「컴퍼스를 1 cm만큼 벌려서 그린 원의 지름은 1 cm예요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X11']::text[],false,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"ox","stem":"「컴퍼스를 1 cm만큼 벌려서 그린 원의 지름은 1 cm예요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"벌린 1 cm는 반지름이라 지름은 2 cm라서","correct":true},{"t":"벌린 길이가 지름이라서","mis":"M3-2-u3-X11"}],"mis":"M3-2-u3-X11","explanation":["벌린 길이 1 cm는 반지름이에요.","지름은 반지름의 2배 — 2 cm예요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#8','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',1,'mc','auto','원 5개로 된 모양을 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],false,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"원 5개로 된 모양을 똑같이 그릴 때 컴퍼스의 침을 꽂아야 할 곳은 모두 몇 군데인가요?","options":[{"t":"5군데","correct":true},{"t":"6군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"10군데","mis":"M3-2-u3-X15"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂아요.","원은 5개예요. 중심이 같은 원은 한 곳에 침을 꽂고 벌린 길이만 바꾸면 돼요.","침을 꽂아야 할 곳(원의 중심)은 5군데예요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[30,60],15],[[60,60],30],[[90,60],45],[[120,60],30],[[150,60],15]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#9','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C4',2,'sa','auto','「드림캐처」 — 작은 드림캐처에 그어진 지름을 재었더니 2 cm였어요. 이 드림캐처의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"「드림캐처」 — 작은 드림캐처에 그어진 지름을 재었더니 2 cm였어요. 이 드림캐처의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["한 원에서 반지름은 지름의 반이에요.","2의 반은 1이에요.","반지름은 1 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#10','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C8',2,'sa','auto','반지름이 1 cm인 원 가와 반지름이 2 cm인 원 나를 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C8","difficulty":2,"kind":"sa","stem":"반지름이 1 cm인 원 가와 반지름이 2 cm인 원 나를 맞닿게 나란히 그렸어요. 두 원의 지름이 한 줄로 이어지도록 그었을 때 왼쪽 끝에서 오른쪽 끝까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["원 가의 지름은 1 × 2 = 2(cm)예요.","원 나의 지름은 2 × 2 = 4(cm)예요.","2 + 4 = 6(cm)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#11','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C4',2,'mc','auto','「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 2 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],false,'{"seq":11,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「카드 뒤집기 놀이」 — 뒤집은 카드 2장에 그려진 원의 반지름이 같으면 카드를 가져가요. 「반지름이 2 cm인 원」 카드와 짝이 되는 카드는 어느 것인가요?","options":[{"t":"지름이 4 cm인 원","correct":true},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X09"},{"t":"반지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 8 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["반지름이 같은지는 「반지름의 2배가 지름과 같은지」로 확인해요.","반지름 2 cm인 원의 지름은 2 × 2 = 4(cm)예요.","그래서 「지름이 4 cm인 원」 카드와 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#12','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',2,'sa','auto','지름이 6 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"지름이 6 cm인 원을 그리려면 컴퍼스의 침과 연필의 끝부분을 몇 cm만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요 — 지름이 주어지면 반지름부터 구해요.","반지름은 지름의 반 — 6 cm의 반은 3 cm예요.","3 cm만큼 벌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#13','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C1',2,'mc','auto','원 위의 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],false,'{"seq":13,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 누름 못과 띠종이로 그린 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄷ만 선 위에 있어요. 점 ㄱ은 원 안, 점 ㄴ은 원 밖에 있어요.","원의 안쪽 부분은 원이 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄷ":[112.5,63.0,"e"],"ㄱ":[62.1,52.2,"nw"],"ㄴ":[75.0,115.5,"s"]},"circle":[[[75,63.0],37.5]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#14','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C2',2,'mc','auto','친구와 손을 잡고, 친구는 제자리에서 나는 그 주변을 한 바퀴 돌아 원을 만들었는데 원이 찌그러졌어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u3-X23']::text[],false,'{"seq":14,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"친구와 손을 잡고, 친구는 제자리에서 나는 그 주변을 한 바퀴 돌아 원을 만들었는데 원이 찌그러졌어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 사람 사이의 거리가 일정하지 않았어요","correct":true},{"t":"제자리에 선 친구가 움직이지 않았어요","mis":"M3-2-u3-X23"},{"t":"한 바퀴를 다 돌았어요","mis":"M3-2-u3-X23"},{"t":"너무 천천히 돌았어요","mis":"M3-2-u3-X23"}],"explanation":["원을 만들려면 중심은 움직이지 않아야 해요.","그리고 중심과 도는 쪽 사이의 거리가 일정해야 해요.","거리가 달라지면 반지름이 일정하지 않아 원이 찌그러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#15','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C7',2,'sa','auto','가운데 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"가운데 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가운데 원의 반지름은 3칸이에요.","지름은 반지름의 2배예요.","3 × 2 = 6칸이에요."],"asset":{"type":"geo","items":[{"w":180,"h":120,"grid":15,"circle":[[[30,60],15],[[60,60],30],[[90,60],45],[[120,60],30],[[150,60],15]],"pts":{"①":[30,60,"n"],"②":[60,60,"n"],"③":[90,60,"n"],"④":[120,60,"n"],"⑤":[150,60,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#16','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C5',2,'mc','auto','「확인 문제」 — 두 문장에 공통으로 들어갈 말은 무엇인가요? (원의 □은/는 원 위의 두 점을 이은 선분 중에서 가장 긴 선분입니다. 원을 똑같이 둘로 나누는 선분은 원의 □입니다.)',ARRAY['M3-2-u3-X17','M3-2-u3-X21','M3-2-u3-X02']::text[],false,'{"seq":16,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"「확인 문제」 — 두 문장에 공통으로 들어갈 말은 무엇인가요? (원의 □은/는 원 위의 두 점을 이은 선분 중에서 가장 긴 선분입니다. 원을 똑같이 둘로 나누는 선분은 원의 □입니다.)","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X17"},{"t":"원의 중심","mis":"M3-2-u3-X21"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 중 가장 긴 선분은 지름이에요.","원을 똑같이 둘로 나누는 선분도 지름이에요.","공통으로 들어갈 말은 「지름」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#17','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',3,'error','auto','컴퍼스로 원을 그리는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M3-2-u3-X11','M3-2-u3-X16']::text[],false,'{"seq":17,"concept":"M3-2-u3-C6","difficulty":3,"kind":"error","stem":"컴퍼스로 원을 그리는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"가람 — 「지름이 4 cm인 원은 컴퍼스를 4 cm만큼 벌려 그려.」","correct":true,"mis_target":"M3-2-u3-X11"},{"t":"민준 — 「먼저 원의 중심이 되는 점을 정해.」","mis":"M3-2-u3-X16"},{"t":"지아 — 「컴퍼스의 침은 원의 중심에 꽂아.」","mis":"M3-2-u3-X16"},{"t":"나은 — 「반지름이 3 cm인 원은 3 cm만큼 벌려.」","mis":"M3-2-u3-X16"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 4 cm인 원은 2 cm만큼 벌려요.","가람이의 말이 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#18','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C3',3,'sa','auto','그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u3-C3","difficulty":3,"kind":"sa","stem":"그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심 가까이를 지나도 중심을 지나지 않는 선분, 중심에서 시작하는 반지름은 빼요.","지름은 2개예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[111.6,49.7,"e"],"ㄴ":[38.4,76.3,"w"],"ㄷ":[68.2,24.6,"n"],"ㄹ":[81.8,101.4,"s"],"ㅁ":[41.2,43.5,"nw"],"ㅂ":[61.7,99.6,"s"],"ㅅ":[108.8,82.5,"se"],"ㅇ":[75,63.0,"nw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#19','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C5',3,'mc','auto','반지름이 4 cm인 원에서 원 위의 두 점을 이은 선분 가운데 가장 긴 선분은 몇 cm인가요?',ARRAY['M3-2-u3-X17','M3-2-u3-X08']::text[],false,'{"seq":19,"concept":"M3-2-u3-C5","difficulty":3,"kind":"mc","stem":"반지름이 4 cm인 원에서 원 위의 두 점을 이은 선분 가운데 가장 긴 선분은 몇 cm인가요?","options":[{"t":"8 cm","correct":true},{"t":"4 cm","mis":"M3-2-u3-X17"},{"t":"2 cm","mis":"M3-2-u3-X08"},{"t":"16 cm","mis":"M3-2-u3-X08"}],"explanation":["가장 긴 선분은 지름이에요.","지름은 반지름의 2배예요.","4 × 2 = 8 — 8 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#20','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',3,'sa','auto','「정보 처리」 — 한 변이 모눈 8칸인 정사각형 안에 무늬가 있어요. 위쪽은 정사각형의 한가운데 점을 원의 중심으로 하여 왼쪽 변의 가운데에서 오른쪽 변의 가운데까지 그린 원의 일부이고, 아래쪽은 정사각형의 아래쪽 두 꼭짓점을 각각 원의 중심으로 하여 그린 원의 일부 2개예요. 이 무늬를 컴퍼스로 똑같이 그리려면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"「정보 처리」 — 한 변이 모눈 8칸인 정사각형 안에 무늬가 있어요. 위쪽은 정사각형의 한가운데 점을 원의 중심으로 하여 왼쪽 변의 가운데에서 오른쪽 변의 가운데까지 그린 원의 일부이고, 아래쪽은 정사각형의 아래쪽 두 꼭짓점을 각각 원의 중심으로 하여 그린 원의 일부 2개예요. 이 무늬를 컴퍼스로 똑같이 그리려면 컴퍼스를 모눈 몇 칸만큼 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["위쪽: 한가운데 점에서 변의 가운데까지 4칸.","아래쪽: 꼭짓점에서 변의 가운데까지 4칸.","4칸만큼 벌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#21','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C7',3,'sa','auto','원이 맞닿게 이어진 그림이에요. 점 ㄴ에서 점 ㅂ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"원이 맞닿게 이어진 그림이에요. 점 ㄴ에서 점 ㅂ까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["둘째 원의 지름 4칸.","셋째 원의 지름 6칸.","4 + 6 = 10칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]],"pts":{"ㄱ":[30,75,"n"],"ㄷ":[75,75,"n"],"ㅁ":[150,75,"n"],"ㅅ":[255,75,"n"],"ㄴ":[45,75,"ne"],"ㄹ":[105,75,"ne"],"ㅂ":[195,75,"ne"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#22','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C5',3,'ox','auto','「어느 원이 더 클까요?」 — 「큰 원들로 둘러싸인 주황색 원보다 작은 원들로 둘러싸인 주황색 원이 실제로 더 커요.」 이 말이 맞나요?',ARRAY['M3-2-u3-X22']::text[],false,'{"seq":22,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"「어느 원이 더 클까요?」 — 「큰 원들로 둘러싸인 주황색 원보다 작은 원들로 둘러싸인 주황색 원이 실제로 더 커요.」 이 말이 맞나요?","answer":"X","reason_options":[{"t":"두 주황색 원의 지름을 재어 보면 같아서","correct":true},{"t":"더 커 보이면 실제로도 커서","mis":"M3-2-u3-X22"}],"mis":"M3-2-u3-X22","explanation":["둘레 그림 때문에 크기가 달라 보이는 것을 착시라고 해요.","지름을 재어 보면 두 원의 크기는 같아요.","이 말은 틀렸어요(X)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#23','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C3',4,'sa','auto','이 원의 지름은 4 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"이 원의 지름은 4 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 2개예요.","한 원에서 지름은 모두 4 cm예요.","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":150,"h":126.0,"pts":{"ㄱ":[111.6,49.7,"e"],"ㄴ":[38.4,76.3,"w"],"ㄷ":[68.2,24.6,"n"],"ㄹ":[81.8,101.4,"s"],"ㅁ":[41.2,43.5,"nw"],"ㅂ":[61.7,99.6,"s"],"ㅅ":[108.8,82.5,"se"],"ㅇ":[75,63.0,"nw"]},"circle":[[[75,63.0],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#24','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C7',4,'sa','auto','이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 반지름이 모눈 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u3-C7","difficulty":4,"kind":"sa","stem":"이 규칙에 맞게 원을 2개 더 그려 원이 모두 6개가 되었어요. 반지름이 모눈 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반지름: 1칸, 2칸이 되풀이돼요.","1, 2, 1, 2, 1, 2.","반지름 2칸인 원은 3개예요."],"asset":{"type":"geo","items":[{"w":165,"h":90,"grid":15,"circle":[[[30,45],15],[[60,45],30],[[90,45],15],[[120,45],30]],"pts":{"①":[30,45,"n"],"②":[60,45,"n"],"③":[90,45,"n"],"④":[120,45,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u3_review_d#25','math',3,2,'u3','','tb_g3_2_math_u3_review_d','unit_review','M3-2-u3-C7',4,'essay','teacher','「나만의 규칙」 — 모눈종이에 컴퍼스로 원 3개를 그려 나만의 모양을 만들려고 해요. 원의 중심과 반지름을 어떻게 정할지 규칙을 쓰고, 컴퍼스의 침을 몇 군데에 꽂게 되는지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C7","difficulty":4,"kind":"essay","stem":"「나만의 규칙」 — 모눈종이에 컴퍼스로 원 3개를 그려 나만의 모양을 만들려고 해요. 원의 중심과 반지름을 어떻게 정할지 규칙을 쓰고, 컴퍼스의 침을 몇 군데에 꽂게 되는지 써 보세요.","answer_guide":{"answer":"예: 반지름이 모눈 3칸인 원을 그리고, 같은 점을 원의 중심으로 하여 반지름 2칸, 1칸인 원을 그린다. 원의 중심이 모두 같으므로 컴퍼스의 침은 한 군데에만 꽂고 벌린 길이만 바꾼다.","scoring_points":["원의 중심을 정하는 규칙을 썼는가","반지름을 정하는 규칙을 썼는가","중심의 수만큼 침을 꽂는다는 것을 바르게 썼는가"]},"explanation":["원의 중심이 같으면 침은 한 군데.","원의 중심이 다르면 중심 수만큼 침을 꽂아요.","반지름만큼 벌려 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
